//  SC_BLM[key] = how a two-method MoV kept as one is answered: RR | OB | CI | CI+SI
var SC_BLQ={"A-001.3":[{"q":"From which month of pregnancy should a pregnant woman start taking one IFA tablet daily?","qh":"गर्भवती महिला को रोज़ एक IFA गोली किस महीने से शुरू करनी चाहिए?","o":["From the first month","From the fourth month (second trimester)","From the seventh month","Only after delivery"],"oh":["पहले महीने से","चौथे महीने से (दूसरी तिमाही)","सातवें महीने से","केवल प्रसव के बाद"],"a":1,"x":"IFA prophylaxis starts in the fourth month and continues daily for at least 180 days in pregnancy, then 180 days after delivery. Folic acid alone is advised from before conception to the end of the first trimester.","xh":"IFA की रोकथाम खुराक चौथे महीने से शुरू होकर गर्भावस्था में कम से कम 180 दिन रोज़ और प्रसव के बाद 180 दिन चलती है। गर्भधारण से पहले से पहली तिमाही तक केवल फोलिक एसिड दिया जाता है।"}],"A-002.1":[{"q":"A pregnant woman at 32 weeks has BP 150/100 mm Hg on two readings and urine albumin 2+. What should the CHO do?","qh":"32 सप्ताह की गर्भवती महिला का BP दो बार 150/100 mm Hg है और पेशाब में एल्ब्यूमिन 2+ है। CHO को क्या करना चाहिए?","o":["Advise rest and review after one month","Recognise pre-eclampsia and refer her to the FRU with a referral slip","Start IFA double dose only","Ask her to reduce salt and come for the next routine ANC"],"oh":["आराम की सलाह देकर एक महीने बाद बुलाएँ","इसे प्री-एक्लेम्पसिया मानकर रेफरल पर्ची के साथ FRU भेजें","केवल IFA की दोगुनी खुराक शुरू करें","नमक कम करने को कहें और अगली नियमित ANC पर बुलाएँ"],"a":1,"x":"High BP with proteinuria is pre-eclampsia, a high-risk condition. It is identified at the SC and referred to the FRU; it is not managed by waiting.","xh":"प्रोटीन-युक्त पेशाब के साथ उच्च BP प्री-एक्लेम्पसिया है, जो उच्च जोखिम वाली स्थिति है। उप-केंद्र पर इसकी पहचान कर FRU रेफर किया जाता है; इंतज़ार नहीं किया जाता।"}],"A-003.2":[{"q":"Which of these is a danger sign during labour that needs urgent referral?","qh":"इनमें से कौन-सा प्रसव के दौरान का खतरे का संकेत है जिसमें तुरंत रेफरल ज़रूरी है?","o":["Regular contractions every 5 minutes","Labour lasting more than 12 hours, or fits","Show (blood-stained mucus) at the start of labour","Urge to pass urine"],"oh":["हर 5 मिनट पर नियमित संकुचन","12 घंटे से अधिक चलने वाला प्रसव, या दौरे पड़ना","प्रसव शुरू होने पर खून मिला म्यूकस (शो)","पेशाब का मन होना"],"a":1,"x":"Prolonged labour (more than 12 hours), convulsions, heavy bleeding, foul-smelling liquor or high fever are danger signs during labour.","xh":"12 घंटे से अधिक लंबा प्रसव, दौरे, अधिक खून बहना, बदबूदार पानी या तेज़ बुखार प्रसव के खतरे के संकेत हैं।"}],"A-004.1":[{"q":"A woman is bleeding heavily after delivery at the SC. What is the first correct step before referral?","qh":"उप-केंद्र पर प्रसव के बाद महिला को बहुत खून बह रहा है। रेफरल से पहले पहला सही कदम क्या है?","o":["Give oral IFA and wait","Start IV fluids, give oxytocin infusion, massage the uterus and refer to the FRU","Refer immediately without any treatment","Give an antibiotic tablet only"],"oh":["मुँह से IFA देकर इंतज़ार करें","IV फ्लूइड शुरू करें, ऑक्सीटोसिन ड्रिप दें, गर्भाशय की मालिश करें और FRU रेफर करें","बिना किसी उपचार के तुरंत रेफर करें","केवल एंटीबायोटिक गोली दें"],"a":1,"x":"PPH is stabilised before referral: IV fluids, oxytocin infusion, uterine massage and bladder catheterisation, then referral with a companion.","xh":"PPH में रेफरल से पहले स्थिति स्थिर करें: IV फ्लूइड, ऑक्सीटोसिन ड्रिप, गर्भाशय की मालिश और पेशाब की नली, फिर साथ में व्यक्ति के साथ रेफर करें।"}],"E-127.1":[{"q":"Within how many weeks of pregnancy should a woman be registered for ANC?","qh":"गर्भावस्था के कितने सप्ताह के अंदर महिला का ANC पंजीकरण हो जाना चाहिए?","o":["Within 12 weeks","Within 20 weeks","Within 28 weeks","At any time before delivery"],"oh":["12 सप्ताह के अंदर","20 सप्ताह के अंदर","28 सप्ताह के अंदर","प्रसव से पहले कभी भी"],"a":0,"x":"Early registration means within the first 12 weeks (first trimester).","xh":"जल्दी पंजीकरण का मतलब है पहले 12 सप्ताह (पहली तिमाही) के अंदर।"}],"E-129.1":[{"q":"How are the expected pregnancies in a Sub-Centre area worked out for a year?","qh":"उप-केंद्र क्षेत्र में एक वर्ष की अपेक्षित गर्भावस्थाएँ कैसे निकाली जाती हैं?","o":["Population × 10%","Birth rate × population ÷ 1000, plus 10%","Number of eligible couples ÷ 2","Last year's deliveries only"],"oh":["जनसंख्या × 10%","जन्म दर × जनसंख्या ÷ 1000, और उसमें 10% जोड़ें","योग्य दंपत्तियों की संख्या ÷ 2","केवल पिछले वर्ष के प्रसव"],"a":1,"x":"Expected live births = crude birth rate × population ÷ 1000; adding about 10% covers abortions and stillbirths, giving expected pregnancies.","xh":"अपेक्षित जीवित जन्म = जन्म दर × जनसंख्या ÷ 1000; इसमें लगभग 10% (गर्भपात और मृत जन्म के लिए) जोड़ने पर अपेक्षित गर्भावस्थाएँ मिलती हैं।"}],"E-131.1":[{"q":"What is the recommended timing of the four ANC check-ups?","qh":"चार ANC जाँचों का अनुशंसित समय क्या है?","o":["Months 1, 3, 5 and 7","Within 12 weeks, 14–26 weeks, 28–34 weeks, and 36 weeks to term","Only in the last three months","Once each trimester and once at delivery"],"oh":["महीना 1, 3, 5 और 7","12 सप्ताह के अंदर, 14–26 सप्ताह, 28–34 सप्ताह, और 36 सप्ताह से प्रसव तक","केवल अंतिम तीन महीनों में","हर तिमाही में एक बार और प्रसव के समय"],"a":1,"x":"First visit within 12 weeks, second at 14–26 weeks, third at 28–34 weeks, fourth from 36 weeks to term.","xh":"पहली जाँच 12 सप्ताह के अंदर, दूसरी 14–26 सप्ताह, तीसरी 28–34 सप्ताह, चौथी 36 सप्ताह से प्रसव तक।"}],"E-133.1":[{"q":"A woman's last menstrual period (LMP) started on 10 January. What is her expected date of delivery (EDD)?","qh":"महिला का अंतिम मासिक धर्म (LMP) 10 जनवरी को शुरू हुआ। उसकी प्रसव की अनुमानित तारीख (EDD) क्या है?","o":["10 September","17 October","10 October","17 November"],"oh":["10 सितंबर","17 अक्टूबर","10 अक्टूबर","17 नवंबर"],"a":1,"x":"EDD = LMP + 9 months + 7 days: 10 January + 9 months = 10 October, + 7 days = 17 October.","xh":"EDD = LMP + 9 महीने + 7 दिन: 10 जनवरी + 9 महीने = 10 अक्टूबर, + 7 दिन = 17 अक्टूबर।"}],"E-133.2":[{"q":"A woman does not remember her LMP. The top of the uterus (fundus) is felt at the level of the navel. About how many weeks pregnant is she?","qh":"महिला को LMP याद नहीं है। गर्भाशय का ऊपरी हिस्सा (फंडस) नाभि के स्तर पर महसूस होता है। वह लगभग कितने सप्ताह की गर्भवती है?","o":["12 weeks","24 weeks","30 weeks","36 weeks"],"oh":["12 सप्ताह","24 सप्ताह","30 सप्ताह","36 सप्ताह"],"a":1,"x":"The fundus is just above the pubic bone at 12 weeks, at the navel at about 24 weeks, and at the lower end of the breastbone (xiphisternum) at about 36 weeks.","xh":"फंडस 12 सप्ताह पर प्यूबिक हड्डी के ठीक ऊपर, लगभग 24 सप्ताह पर नाभि पर, और लगभग 36 सप्ताह पर छाती की हड्डी के निचले सिरे (ज़िफ़िस्टर्नम) तक होता है।"}],"E-136.2":[{"q":"What is the normal foetal heart rate?","qh":"भ्रूण की सामान्य हृदय गति क्या है?","o":["60–100 beats per minute","110–160 beats per minute","170–200 beats per minute","Any rate is normal if the heart sound is heard"],"oh":["60–100 धड़कन प्रति मिनट","110–160 धड़कन प्रति मिनट","170–200 धड़कन प्रति मिनट","आवाज़ सुनाई दे तो कोई भी गति सामान्य है"],"a":1,"x":"A foetal heart rate below 110 or above 160 per minute, counted for a full minute, needs action and referral.","xh":"पूरे एक मिनट गिनने पर 110 से कम या 160 से अधिक भ्रूण हृदय गति पर कार्रवाई और रेफरल ज़रूरी है।"}],"E-139.1":[{"q":"Which of these pregnant women must be referred to a higher centre?","qh":"इनमें से किस गर्भवती महिला को उच्च केंद्र पर रेफर करना ज़रूरी है?","o":["A woman with Hb 11.5 g/dl","A woman with bleeding from the vagina in the eighth month (APH)","A woman with mild morning sickness in the second month","A woman who feels the baby move"],"oh":["Hb 11.5 g/dl वाली महिला","आठवें महीने में योनि से खून आने वाली महिला (APH)","दूसरे महीने में हल्की मॉर्निंग सिकनेस वाली महिला","बच्चे की हलचल महसूस करने वाली महिला"],"a":1,"x":"Antepartum haemorrhage, severe anaemia, PIH, malpresentation, bad obstetric history, PROM and obstructed labour are referred.","xh":"प्रसव-पूर्व रक्तस्राव (APH), गंभीर एनीमिया, PIH, गलत स्थिति, खराब प्रसूति इतिहास, PROM और रुका हुआ प्रसव रेफर किए जाते हैं।"}],"E-140.1":[{"q":"When is a pregnant woman said to have hypertension?","qh":"गर्भवती महिला को उच्च रक्तचाप (हाइपरटेंशन) कब माना जाता है?","o":["One reading of 130/80 mm Hg","Two readings 4 hours apart with systolic 140 or more and/or diastolic 90 or more","Any reading above 120/80 mm Hg","Only if she has a headache"],"oh":["130/80 mm Hg की एक रीडिंग","4 घंटे के अंतर पर दो रीडिंग में सिस्टोलिक 140 या अधिक और/या डायस्टोलिक 90 या अधिक","120/80 mm Hg से ऊपर कोई भी रीडिंग","केवल सिरदर्द होने पर"],"a":1,"x":"Hypertension in pregnancy: BP 140/90 mm Hg or more on two readings taken 4 hours apart.","xh":"गर्भावस्था में उच्च रक्तचाप: 4 घंटे के अंतर पर ली गई दो रीडिंग में BP 140/90 mm Hg या अधिक।"}],"E-141.2":[{"q":"Which signs together point to imminent eclampsia?","qh":"कौन-से लक्षण एक साथ आसन्न एक्लेम्पसिया (दौरे का खतरा) दर्शाते हैं?","o":["BP 110/70 with mild swelling of the feet","BP above 140/90 with albumin 2+, severe headache, blurred vision and pain in the upper abdomen","Low-grade fever with cough","Back pain in the ninth month"],"oh":["BP 110/70 और पैरों में हल्की सूजन","BP 140/90 से ऊपर, एल्ब्यूमिन 2+, तेज़ सिरदर्द, धुंधला दिखना और पेट के ऊपरी हिस्से में दर्द","खाँसी के साथ हल्का बुखार","नौवें महीने में कमर दर्द"],"a":1,"x":"Severe headache, blurred vision, epigastric pain and low urine output with high BP and proteinuria mean fits may come soon; give the first dose of magnesium sulphate and refer.","xh":"उच्च BP और प्रोटीन के साथ तेज़ सिरदर्द, धुंधला दिखना, पेट के ऊपर दर्द और कम पेशाब का मतलब है कि जल्द दौरे पड़ सकते हैं; मैग्नीशियम सल्फेट की पहली खुराक देकर रेफर करें।"}],"E-143.1":[{"q":"A pregnant woman's haemoglobin is 8.5 g/dl. How is her anaemia classified?","qh":"गर्भवती महिला का हीमोग्लोबिन 8.5 g/dl है। उसके एनीमिया को किस श्रेणी में रखा जाएगा?","o":["No anaemia","Mild anaemia","Moderate anaemia","Severe anaemia"],"oh":["एनीमिया नहीं","हल्का एनीमिया","मध्यम एनीमिया","गंभीर एनीमिया"],"a":2,"x":"In pregnancy: 11 g/dl or more = no anaemia; 10–10.9 = mild; 7–9.9 = moderate; below 7 = severe.","xh":"गर्भावस्था में: 11 g/dl या अधिक = एनीमिया नहीं; 10–10.9 = हल्का; 7–9.9 = मध्यम; 7 से कम = गंभीर।"}],"E-144.1":[{"q":"For how long should a pregnant woman take prophylactic IFA?","qh":"गर्भवती महिला को रोकथाम के लिए IFA कितने समय तक लेनी चाहिए?","o":["30 days in pregnancy","At least 180 days in pregnancy and 180 days after delivery","Only during the last month","Until the first ANC visit"],"oh":["गर्भावस्था में 30 दिन","गर्भावस्था में कम से कम 180 दिन और प्रसव के बाद 180 दिन","केवल अंतिम महीने में","पहली ANC जाँच तक"],"a":1,"x":"One IFA tablet (60 mg iron + 500 mcg folic acid) daily from the fourth month for at least 180 days, continued for 180 days after delivery.","xh":"चौथे महीने से रोज़ एक IFA गोली (60 mg आयरन + 500 mcg फोलिक एसिड) कम से कम 180 दिन, और प्रसव के बाद 180 दिन।"}],"E-144.2":[{"q":"A pregnant woman has mild or moderate anaemia. What is the usual oral IFA treatment?","qh":"गर्भवती महिला को हल्का या मध्यम एनीमिया है। मुँह से दी जाने वाली IFA का सामान्य उपचार क्या है?","o":["One tablet a week","One tablet a day","Two tablets a day (double dose)","IFA is stopped"],"oh":["सप्ताह में एक गोली","रोज़ एक गोली","रोज़ दो गोली (दोगुनी खुराक)","IFA बंद कर दी जाती है"],"a":2,"x":"Treatment of anaemia is a double dose: two IFA tablets daily, with a Hb check after a month; severe anaemia is referred.","xh":"एनीमिया का उपचार दोगुनी खुराक है: रोज़ दो IFA गोली, एक महीने बाद Hb जाँच; गंभीर एनीमिया रेफर किया जाता है।"}],"E-147.2":[{"q":"When should breastfeeding start after a normal delivery?","qh":"सामान्य प्रसव के बाद स्तनपान कब शुरू होना चाहिए?","o":["Within one hour of birth","After 6 hours","After the mother's milk \"comes in\" on day 3","After giving honey or water first"],"oh":["जन्म के एक घंटे के अंदर","6 घंटे बाद","तीसरे दिन दूध आने के बाद","पहले शहद या पानी देने के बाद"],"a":0,"x":"Start within the first hour (colostrum), give no pre-lacteal feeds, and breastfeed exclusively for six months.","xh":"पहले घंटे के अंदर शुरू करें (कोलोस्ट्रम), पहले कुछ भी न दें (न शहद, न पानी), और छह महीने तक केवल स्तनपान कराएँ।"}],"E-147.3":[{"q":"When can a post-partum IUCD (PPIUCD) be inserted?","qh":"प्रसव के बाद IUCD (PPIUCD) कब लगाई जा सकती है?","o":["Only 6 months after delivery","Within 10 minutes of delivery of the placenta, or within 48 hours of delivery","Only after the first period returns","Only after a caesarean section"],"oh":["केवल प्रसव के 6 महीने बाद","आँवल निकलने के 10 मिनट के अंदर, या प्रसव के 48 घंटे के अंदर","केवल पहला मासिक धर्म आने के बाद","केवल सिज़ेरियन के बाद"],"a":1,"x":"PPIUCD is inserted within 10 minutes of placental delivery (post-placental) or within 48 hours of delivery, by a trained provider.","xh":"PPIUCD आँवल निकलने के 10 मिनट के अंदर या प्रसव के 48 घंटे के अंदर प्रशिक्षित व्यक्ति द्वारा लगाई जाती है।"}],"E-149.1":[{"q":"Which of these is one of the \"six cleans\" of delivery?","qh":"इनमें से कौन-सा प्रसव के \"छह साफ़\" में से एक है?","o":["Clean blade to cut the cord","Clean bottle for formula milk","Clean pillow for the mother","Clean water to bathe the baby immediately"],"oh":["नाल काटने के लिए साफ़ ब्लेड","फ़ॉर्मूला दूध के लिए साफ़ बोतल","माँ के लिए साफ़ तकिया","बच्चे को तुरंत नहलाने के लिए साफ़ पानी"],"a":0,"x":"The six cleans: clean hands, clean surface, clean blade, clean cord tie, clean towel to dry the baby, and clean cloth to wrap the mother.","xh":"छह साफ़: साफ़ हाथ, साफ़ सतह, साफ़ ब्लेड, साफ़ नाल-धागा, बच्चे को पोंछने का साफ़ तौलिया, और माँ को ढकने का साफ़ कपड़ा।"}],"E-150.1":[{"q":"Should episiotomy be done for every woman delivering for the first time?","qh":"क्या पहली बार प्रसव करने वाली हर महिला का एपिसियोटॉमी (चीरा) करना चाहिए?","o":["Yes, always","No — only when there is a clear reason (e.g. foetal distress, rigid perineum)","Yes, if the baby is a boy","Only if the woman asks"],"oh":["हाँ, हमेशा","नहीं — केवल स्पष्ट कारण होने पर (जैसे भ्रूण संकट, कठोर पेरिनियम)","हाँ, अगर लड़का हो","केवल महिला के कहने पर"],"a":1,"x":"Routine episiotomy is not recommended; it is done only on clear indication.","xh":"नियमित एपिसियोटॉमी की सलाह नहीं दी जाती; यह केवल स्पष्ट कारण होने पर की जाती है।"}],"E-150.2":[{"q":"Can oxytocin be given to speed up normal labour at the Sub-Centre?","qh":"क्या उप-केंद्र पर सामान्य प्रसव को तेज़ करने के लिए ऑक्सीटोसिन दी जा सकती है?","o":["Yes, to every woman in labour","No — oxytocin or misoprostol must not be used to induce or speed up labour at the SC","Yes, if labour seems slow","Yes, if the family asks"],"oh":["हाँ, हर प्रसव में","नहीं — उप-केंद्र पर प्रसव शुरू करने या तेज़ करने के लिए ऑक्सीटोसिन या मिसोप्रोस्टोल नहीं दी जाती","हाँ, अगर प्रसव धीमा लगे","हाँ, अगर परिवार कहे"],"a":1,"x":"Using uterotonics before delivery of the baby can rupture the uterus or harm the baby. Slow labour is referred; oxytocin is for AMTSL after the birth.","xh":"बच्चे के जन्म से पहले ऐसी दवा देने से गर्भाशय फट सकता है या बच्चे को नुकसान हो सकता है। धीमा प्रसव रेफर किया जाता है; ऑक्सीटोसिन जन्म के बाद AMTSL के लिए है।"}],"E-151.1":[{"q":"Which of these is part of active management of the third stage of labour (AMTSL)?","qh":"इनमें से कौन-सा प्रसव के तीसरे चरण के सक्रिय प्रबंधन (AMTSL) का हिस्सा है?","o":["Pulling the cord hard before the uterus contracts","A uterotonic within 1 minute, controlled cord traction during a contraction, and uterine massage","Waiting 2 hours for the placenta without doing anything","Pressing hard on the fundus to push the placenta out"],"oh":["गर्भाशय सिकुड़ने से पहले नाल को ज़ोर से खींचना","1 मिनट के अंदर गर्भाशय-संकुचक दवा, संकुचन के समय नियंत्रित नाल खिंचाव, और गर्भाशय की मालिश","बिना कुछ किए 2 घंटे आँवल का इंतज़ार","आँवल निकालने के लिए फंडस पर ज़ोर से दबाना"],"a":1,"x":"AMTSL: rule out a second baby, uterotonic within 1 minute, controlled cord traction with counter-traction during a contraction, uterine massage, and check the placenta is complete.","xh":"AMTSL: दूसरे बच्चे की जाँच, 1 मिनट के अंदर गर्भाशय-संकुचक दवा, संकुचन के समय नियंत्रित नाल खिंचाव, गर्भाशय की मालिश, और आँवल पूरा होने की जाँच।"}],"E-152.1":[{"q":"What is the correct uterotonic dose in AMTSL?","qh":"AMTSL में गर्भाशय-संकुचक दवा की सही खुराक क्या है?","o":["Oxytocin 10 IU IM within 1 minute of birth","Oxytocin 2 IU IV before birth","Oxytocin 10 IU IM 30 minutes after the placenta","Misoprostol 25 mcg before birth"],"oh":["जन्म के 1 मिनट के अंदर ऑक्सीटोसिन 10 IU IM","जन्म से पहले ऑक्सीटोसिन 2 IU IV","आँवल निकलने के 30 मिनट बाद ऑक्सीटोसिन 10 IU IM","जन्म से पहले मिसोप्रोस्टोल 25 mcg"],"a":0,"x":"Oxytocin 10 IU IM within one minute of the birth of the baby, after ruling out another baby. If oxytocin is not available, misoprostol 600 mcg orally.","xh":"दूसरा बच्चा न होने की पुष्टि के बाद, बच्चे के जन्म के एक मिनट के अंदर ऑक्सीटोसिन 10 IU IM। ऑक्सीटोसिन न हो तो मिसोप्रोस्टोल 600 mcg मुँह से।"}],"E-154.1":[{"q":"When should the cord be clamped and cut in a baby who is breathing well?","qh":"अच्छी तरह साँस ले रहे बच्चे की नाल कब बाँधी और काटी जानी चाहिए?","o":["Immediately at birth","After 1–3 minutes (delayed cord clamping)","After the placenta is delivered, at about 30 minutes","After the first bath"],"oh":["जन्म होते ही तुरंत","1–3 मिनट बाद (देर से नाल बाँधना)","आँवल निकलने के बाद, लगभग 30 मिनट पर","पहले स्नान के बाद"],"a":1,"x":"Delayed cord clamping at 1–3 minutes gives the baby more blood and iron; it is skipped only if the baby needs resuscitation.","xh":"1–3 मिनट बाद नाल बाँधने से बच्चे को अधिक खून और आयरन मिलता है; केवल पुनर्जीवन (रिससिटेशन) की ज़रूरत हो तो ऐसा नहीं करते।"}],"E-155.2":[{"q":"What dose of Vitamin K is given to a newborn weighing 2.5 kg?","qh":"2.5 kg वज़न वाले नवजात को विटामिन K की कितनी खुराक दी जाती है?","o":["1 mg IM","0.1 mg IM","5 mg orally","Vitamin K is not given"],"oh":["1 mg IM","0.1 mg IM","5 mg मुँह से","विटामिन K नहीं दिया जाता"],"a":0,"x":"Vitamin K 1 mg IM at birth (0.5 mg for babies under 1000 g), to prevent bleeding.","xh":"जन्म पर विटामिन K 1 mg IM (1000 g से कम वज़न पर 0.5 mg), खून बहने से रोकने के लिए।"}],"E-156.1":[{"q":"A newborn is not breathing after drying and stimulation. Within how long should bag-and-mask ventilation start?","qh":"पोंछने और उत्तेजित करने के बाद भी नवजात साँस नहीं ले रहा। बैग-और-मास्क से साँस कितने समय में शुरू होनी चाहिए?","o":["Within the first minute after birth (the \"golden minute\")","After 10 minutes","After the placenta is delivered","Only after the doctor arrives"],"oh":["जन्म के बाद पहले मिनट के अंदर (\"गोल्डन मिनट\")","10 मिनट बाद","आँवल निकलने के बाद","केवल डॉक्टर के आने के बाद"],"a":0,"x":"If the baby is not breathing after drying and stimulation, start bag-and-mask ventilation within the first minute of birth.","xh":"पोंछने और उत्तेजित करने के बाद भी बच्चा साँस न ले तो जन्म के पहले मिनट के अंदर बैग-और-मास्क से साँस देना शुरू करें।"}],"E-157.1":[{"q":"In active labour, what rate of cervical dilatation is slow and needs action?","qh":"सक्रिय प्रसव में गर्भाशय-मुख खुलने की कौन-सी गति धीमी मानी जाती है जिस पर कार्रवाई ज़रूरी है?","o":["Less than 1 cm per hour","2 cm per hour","3 cm per hour","Any rate is normal"],"oh":["1 cm प्रति घंटे से कम","2 cm प्रति घंटा","3 cm प्रति घंटा","कोई भी गति सामान्य है"],"a":0,"x":"In active labour the cervix should open about 1 cm per hour; slower progress (the partograph moving to the right of the alert line) needs action.","xh":"सक्रिय प्रसव में गर्भाशय-मुख लगभग 1 cm प्रति घंटा खुलना चाहिए; इससे धीमी प्रगति (पार्टोग्राफ़ पर अलर्ट लाइन के दाईं ओर) पर कार्रवाई ज़रूरी है।"}],"E-157.2":[{"q":"On the partograph, the dilatation line crosses the ALERT line at a Sub-Centre. What should be done?","qh":"उप-केंद्र पर पार्टोग्राफ़ में गर्भाशय-मुख की रेखा अलर्ट लाइन को पार कर जाती है। क्या करना चाहिए?","o":["Nothing, wait for the action line","Refer the woman to the FRU","Give oxytocin to speed up labour","Stop recording the partograph"],"oh":["कुछ नहीं, एक्शन लाइन का इंतज़ार करें","महिला को FRU रेफर करें","प्रसव तेज़ करने के लिए ऑक्सीटोसिन दें","पार्टोग्राफ़ भरना बंद करें"],"a":1,"x":"At a Sub-Centre, crossing the alert line means referral to a facility that can manage prolonged labour; the action line is where intervention is needed.","xh":"उप-केंद्र पर अलर्ट लाइन पार होने का मतलब है लंबे प्रसव को संभाल सकने वाले केंद्र पर रेफरल; एक्शन लाइन पर हस्तक्षेप ज़रूरी होता है।"}],"E-158.2":[{"q":"A woman in labour has a fit, with high BP and protein in urine. What is the correct first dose of magnesium sulphate before referral?","qh":"प्रसव में महिला को दौरा पड़ता है, BP ज़्यादा है और पेशाब में प्रोटीन है। रेफरल से पहले मैग्नीशियम सल्फेट की सही पहली खुराक क्या है?","o":["5 g (10 ml of 50%) deep IM in each buttock — 10 g in all","1 g orally","2 ml IV only","No drug — refer only"],"oh":["हर नितंब में 5 g (50% का 10 ml) गहरा IM — कुल 10 g","1 g मुँह से","केवल 2 ml IV","कोई दवा नहीं — केवल रेफर करें"],"a":0,"x":"Pre-referral loading dose: 5 g (10 ml of 50% solution) deep IM in each buttock, then refer to the FRU if delivery is not imminent.","xh":"रेफरल से पहले लोडिंग खुराक: हर नितंब में 5 g (50% घोल का 10 ml) गहरा IM, फिर प्रसव तुरंत न हो तो FRU रेफर करें।"}],"E-159.1":[{"q":"When is bleeding after delivery called postpartum haemorrhage (PPH)?","qh":"प्रसव के बाद खून बहने को प्रसवोत्तर रक्तस्राव (PPH) कब कहा जाता है?","o":["More than 100 ml","More than 500 ml, or one pad soaked in less than 5 minutes","Any bleeding on the first day","Only if the woman faints"],"oh":["100 ml से अधिक","500 ml से अधिक, या 5 मिनट से कम में एक पैड भीग जाना","पहले दिन कोई भी खून","केवल महिला के बेहोश होने पर"],"a":1,"x":"PPH: blood loss of 500 ml or more after vaginal delivery, or a pad soaked in under 5 minutes; any bleeding that makes the woman unstable also counts.","xh":"PPH: सामान्य प्रसव के बाद 500 ml या अधिक खून, या 5 मिनट से कम में पैड भीग जाना; महिला की हालत बिगाड़ने वाला कोई भी रक्तस्राव भी PPH है।"}],"E-159.2":[{"q":"How is oxytocin given as an infusion for PPH?","qh":"PPH में ऑक्सीटोसिन ड्रिप कैसे दी जाती है?","o":["20 IU in 1 litre NS/RL at 60 drops per minute","5 IU in 100 ml at 10 drops per minute","100 IU IV push","Oxytocin is not used for PPH"],"oh":["1 लीटर NS/RL में 20 IU, 60 बूंद प्रति मिनट","100 ml में 5 IU, 10 बूंद प्रति मिनट","100 IU IV एक साथ","PPH में ऑक्सीटोसिन नहीं दी जाती"],"a":0,"x":"Oxytocin 20 IU in 1 L normal saline or Ringer lactate at 60 drops per minute, with uterine massage and catheterisation, then referral.","xh":"1 लीटर नॉर्मल सलाइन या रिंगर लैक्टेट में ऑक्सीटोसिन 20 IU, 60 बूंद प्रति मिनट, साथ में गर्भाशय की मालिश और कैथेटर, फिर रेफरल।"}],"A-005.1":[{"q":"A newborn is weighed at birth. Below what weight must the baby be referred to a higher centre?","qh":"जन्म पर नवजात का वज़न लिया गया। कितने से कम वज़न पर बच्चे को उच्च केंद्र रेफर करना ज़रूरी है?","o":["Below 3000 g","Below 2500 g","Below 1800 g","Below 1000 g only"],"oh":["3000 g से कम","2500 g से कम","1800 g से कम","केवल 1000 g से कम"],"a":2,"x":"Babies under 1800 g (or born before 34 weeks) are referred to an SNCU/NBSU; babies 1800–2499 g need extra care at home and close follow-up.","xh":"1800 g से कम (या 34 सप्ताह से पहले जन्मे) बच्चे SNCU/NBSU रेफर किए जाते हैं; 1800–2499 g वाले बच्चों को घर पर अतिरिक्त देखभाल और नज़दीकी फ़ॉलो-अप चाहिए।"}],"E-089.1":[{"q":"Which of these is a danger sign in a newborn?","qh":"इनमें से कौन-सा नवजात में खतरे का संकेत है?","o":["Sneezing","Not able to breastfeed, or convulsions","Passing yellow stool after feeds","Sleeping most of the day but feeding well"],"oh":["छींक आना","स्तनपान न कर पाना, या दौरे पड़ना","दूध पीने के बाद पीली टट्टी","दिन में ज़्यादा सोना पर ठीक से दूध पीना"],"a":1,"x":"Danger signs include inability to feed, convulsions, lethargy, fast breathing, chest in-drawing, fever or low temperature, jaundice on day 1 or on palms/soles, and pus from the cord.","xh":"खतरे के संकेत: दूध न पी पाना, दौरे, सुस्ती, तेज़ साँस, छाती धँसना, बुखार या ठंडा शरीर, पहले दिन या हथेली/तलवों पर पीलिया, और नाल से मवाद।"}],"E-110.1":[{"q":"In a young infant (up to 2 months), what breathing rate counts as fast breathing?","qh":"छोटे शिशु (2 महीने तक) में कितनी साँस दर तेज़ मानी जाती है?","o":["30 or more per minute","40 or more per minute","60 or more per minute","80 or more per minute"],"oh":["30 या अधिक प्रति मिनट","40 या अधिक प्रति मिनट","60 या अधिक प्रति मिनट","80 या अधिक प्रति मिनट"],"a":2,"x":"In a young infant, 60 or more breaths per minute (counted for a full minute, repeated if high) is fast breathing — a sign of possible serious bacterial infection.","xh":"छोटे शिशु में 60 या अधिक साँस प्रति मिनट (पूरे एक मिनट गिनकर, ज़्यादा हो तो दोबारा गिनें) तेज़ साँस है — संभावित गंभीर संक्रमण का संकेत।"}],"E-113.1":[{"q":"A young infant has signs of possible serious bacterial infection. What is given before urgent referral?","qh":"छोटे शिशु में संभावित गंभीर बैक्टीरियल संक्रमण के संकेत हैं। तुरंत रेफरल से पहले क्या दिया जाता है?","o":["Nothing — refer only","First dose of oral amoxicillin and injection gentamicin","ORS only","Cough syrup"],"oh":["कुछ नहीं — केवल रेफर करें","मुँह से अमोक्सिसिलिन और इंजेक्शन जेंटामाइसिन की पहली खुराक","केवल ORS","खाँसी का सिरप"],"a":1,"x":"Pre-referral: first dose of oral amoxicillin and IM gentamicin, prevent low blood sugar with breast milk, and keep the baby warm on the way.","xh":"रेफरल से पहले: मुँह से अमोक्सिसिलिन और IM जेंटामाइसिन की पहली खुराक, माँ के दूध से कम शुगर से बचाव, और रास्ते में बच्चे को गर्म रखना।"}],"E-113.3":[{"q":"A young infant's axillary temperature is 35 °C. What should be done first?","qh":"छोटे शिशु का बगल का तापमान 35 °C है। पहले क्या करना चाहिए?","o":["Give a cold sponge","Warm the baby skin-to-skin with the mother (Kangaroo care) and cover the head","Bathe the baby in warm water","Give paracetamol"],"oh":["ठंडे पानी से पोंछें","माँ के साथ त्वचा-से-त्वचा संपर्क (कंगारू देखभाल) से गर्म करें और सिर ढकें","गुनगुने पानी से नहलाएँ","पैरासिटामोल दें"],"a":1,"x":"Below 35.5 °C the infant is too cold: warm skin-to-skin, cover the head and feet, keep breastfeeding, and refer if the temperature does not rise.","xh":"35.5 °C से कम पर शिशु बहुत ठंडा है: त्वचा-से-त्वचा संपर्क से गर्म करें, सिर और पैर ढकें, स्तनपान जारी रखें, और तापमान न बढ़े तो रेफर करें।"}],"E-093.1":[{"q":"How long can a reconstituted BCG, MR or JE vial be used?","qh":"घोले गए (reconstituted) BCG, MR या JE वायल का उपयोग कितने समय तक किया जा सकता है?","o":["Up to 4 hours after reconstitution","Up to 24 hours","Up to 4 weeks","Until the end of the next session"],"oh":["घोलने के 4 घंटे तक","24 घंटे तक","4 सप्ताह तक","अगले सत्र के अंत तक"],"a":0,"x":"Reconstituted BCG, MR, JE (and rotavirus once opened) are discarded 4 hours after opening, whatever the VVM shows.","xh":"घोले गए BCG, MR, JE (और खुला रोटावायरस) खोलने के 4 घंटे बाद फेंक दिए जाते हैं, VVM कुछ भी दिखाए।"}],"E-094.1":[{"q":"When does the vaccine vial monitor (VVM) show that a vaccine must be discarded?","qh":"वैक्सीन वायल मॉनिटर (VVM) कब बताता है कि टीका फेंक देना चाहिए?","o":["When the inner square is lighter than the outer circle","When the inner square matches or is darker than the outer circle","When the label is wet","VVM does not decide use"],"oh":["जब अंदर का चौकोर बाहर के गोले से हल्का हो","जब अंदर का चौकोर बाहर के गोले जैसा या उससे गहरा हो","जब लेबल गीला हो","VVM से उपयोग तय नहीं होता"],"a":1,"x":"If the inner square is the same colour as or darker than the outer circle, the discard point is reached — do not use the vial.","xh":"अगर अंदर का चौकोर बाहर के गोले जैसा या उससे गहरा है, तो फेंकने का बिंदु आ गया है — वायल का उपयोग न करें।"}],"E-094.2":[{"q":"How does the shake test show that a freeze-sensitive vaccine (e.g. Pentavalent, DPT, Hep B) was damaged by freezing?","qh":"शेक टेस्ट कैसे बताता है कि फ्रीज़-संवेदनशील टीका (जैसे पेंटावैलेंट, DPT, हेप B) जमने से खराब हो गया?","o":["The suspect vial settles at the same speed as, or faster than, a vial frozen on purpose","The suspect vial changes colour","The suspect vial feels warm","The VVM turns white"],"oh":["संदिग्ध वायल जानबूझकर जमाए गए वायल जितनी या उससे तेज़ी से नीचे बैठता है","संदिग्ध वायल का रंग बदल जाता है","संदिग्ध वायल गर्म लगता है","VVM सफ़ेद हो जाता है"],"a":0,"x":"Shake the suspect vial and a control vial frozen on purpose. If the suspect vial settles as fast as or faster than the control, it was frozen — discard it. If it settles more slowly, it can be used.","xh":"संदिग्ध वायल और जानबूझकर जमाए गए नियंत्रण वायल को हिलाएँ। संदिग्ध वायल नियंत्रण जितनी या उससे तेज़ी से बैठे तो वह जमा था — फेंक दें। धीरे बैठे तो उपयोग कर सकते हैं।"}],"E-095.3":[{"q":"A child has mild fever and pain at the injection site after Pentavalent vaccine. What is this and what is done?","qh":"पेंटावैलेंट टीके के बाद बच्चे को हल्का बुखार और इंजेक्शन की जगह दर्द है। यह क्या है और क्या किया जाता है?","o":["A serious AEFI — refer immediately","A minor AEFI — reassure the parents and give paracetamol if needed","Vaccine failure — repeat the dose","An allergy — stop all vaccines"],"oh":["गंभीर AEFI — तुरंत रेफर करें","मामूली AEFI — माता-पिता को आश्वस्त करें और ज़रूरत हो तो पैरासिटामोल दें","टीके की विफलता — खुराक दोहराएँ","एलर्जी — सभी टीके बंद करें"],"a":1,"x":"Mild fever, local pain or swelling are minor AEFI; they settle on their own. Parents are told about them in advance.","xh":"हल्का बुखार, स्थानीय दर्द या सूजन मामूली AEFI हैं; ये अपने आप ठीक हो जाते हैं। माता-पिता को पहले से बताया जाता है।"}],"E-096.1":[{"q":"A child develops anaphylaxis minutes after a vaccine. What is the first drug to give?","qh":"टीके के कुछ मिनट बाद बच्चे को एनाफिलेक्सिस हो जाता है। सबसे पहले कौन-सी दवा दें?","o":["Paracetamol syrup","Adrenaline (1:1000) IM","ORS","Oral antihistamine only"],"oh":["पैरासिटामोल सिरप","एड्रेनालिन (1:1000) IM","ORS","केवल मुँह से एंटीहिस्टामिन"],"a":1,"x":"Adrenaline 1:1000 IM in the thigh is the first drug for anaphylaxis; then lay the child down, keep the airway open and refer. Keep the AEFI kit at every session.","xh":"एनाफिलेक्सिस में पहली दवा जाँघ में एड्रेनालिन 1:1000 IM है; फिर बच्चे को लिटाएँ, साँस का रास्ता खुला रखें और रेफर करें। हर सत्र में AEFI किट रखें।"}],"E-099.1":[{"q":"How long can an opened bottle of Vitamin A solution be used?","qh":"विटामिन A घोल की खुली बोतल कितने समय तक उपयोग की जा सकती है?","o":["24 hours","1 week","8 weeks (date of opening written on the label)","Until the bottle is finished, however long"],"oh":["24 घंटे","1 सप्ताह","8 सप्ताह (लेबल पर खोलने की तारीख लिखें)","बोतल खत्म होने तक, चाहे जितना समय लगे"],"a":2,"x":"Once opened, Vitamin A solution is used within 8 weeks; write the opening date on the label and keep it away from sunlight.","xh":"खुलने के बाद विटामिन A घोल 8 सप्ताह के अंदर उपयोग करें; लेबल पर खोलने की तारीख लिखें और धूप से बचाएँ।"}],"E-100.1":[{"q":"What should be done with used and unused vaccine vials at the end of an outreach session?","qh":"आउटरीच सत्र के अंत में इस्तेमाल हुए और न हुए टीके के वायल का क्या करना चाहिए?","o":["Keep them at the AWC for the next session","Put them in a zip bag in the vaccine carrier and return them to the cold chain point the same day (reverse cold chain)","Throw all opened vials in the dustbin","Take them home in the fridge"],"oh":["अगले सत्र के लिए आंगनवाड़ी में रख दें","ज़िप बैग में वैक्सीन कैरियर में रखकर उसी दिन कोल्ड चेन पॉइंट पर लौटाएँ (रिवर्स कोल्ड चेन)","सभी खुले वायल कूड़ेदान में फेंक दें","घर के फ्रिज में ले जाएँ"],"a":1,"x":"Used and unused vials go back in the carrier to the cold chain point the same day, through the alternate vaccine delivery (AVD) system.","xh":"इस्तेमाल और बिना इस्तेमाल वायल उसी दिन कैरियर में वैकल्पिक टीका वितरण (AVD) के ज़रिए कोल्ड चेन पॉइंट पर लौटाए जाते हैं।"}],"E-101.1":[{"q":"Which vaccine is NOT covered by the open vial policy?","qh":"कौन-सा टीका ओपन वायल पॉलिसी में शामिल नहीं है?","o":["Pentavalent","OPV","Measles-Rubella (MR)","Td"],"oh":["पेंटावैलेंट","OPV","मीज़ल्स-रूबेला (MR)","Td"],"a":2,"x":"The open vial policy does not apply to reconstituted vaccines — BCG, MR and JE — or to rotavirus; these are used within 4 hours.","xh":"ओपन वायल पॉलिसी घोले जाने वाले टीकों — BCG, MR, JE — और रोटावायरस पर लागू नहीं होती; इन्हें 4 घंटे के अंदर उपयोग किया जाता है।"}],"E-102.2":[{"q":"Under the open vial policy, for how long can an opened Pentavalent vial be used in later sessions?","qh":"ओपन वायल पॉलिसी के तहत खुला पेंटावैलेंट वायल बाद के सत्रों में कितने समय तक इस्तेमाल हो सकता है?","o":["Up to 4 hours","Up to 7 days","Up to 4 weeks (28 days) if all OVP conditions are met","Until the expiry date on the label"],"oh":["4 घंटे तक","7 दिन तक","सभी शर्तें पूरी हों तो 4 सप्ताह (28 दिन) तक","लेबल की समाप्ति तारीख तक"],"a":2,"x":"Up to 28 days if: within expiry, cold chain kept, VVM not at discard point, septum not submerged, aseptic technique used, and the date and time of opening are written on the vial.","xh":"28 दिन तक, अगर: समाप्ति तारीख के अंदर हो, कोल्ड चेन बनी रहे, VVM फेंकने के बिंदु पर न हो, ढक्कन पानी में न डूबा हो, साफ़ तरीका अपनाया गया हो, और वायल पर खोलने की तारीख व समय लिखा हो।"}],"E-104.1":[{"q":"Which of these is a SERIOUS AEFI?","qh":"इनमें से कौन-सा गंभीर AEFI है?","o":["Mild fever on the same day","Pain and redness at the injection site","Death, hospitalisation, disability or a cluster of cases after vaccination","Crying for a short time after the injection"],"oh":["उसी दिन हल्का बुखार","इंजेक्शन की जगह दर्द और लाली","टीकाकरण के बाद मृत्यु, अस्पताल में भर्ती, विकलांगता या कई मामलों का समूह","इंजेक्शन के बाद थोड़ी देर रोना"],"a":2,"x":"Serious AEFI: death, life-threatening event, hospitalisation, disability, or a cluster of events, or one causing community concern. These are reported and investigated.","xh":"गंभीर AEFI: मृत्यु, जान का खतरा, अस्पताल में भर्ती, विकलांगता, मामलों का समूह, या समुदाय में चिंता पैदा करने वाली घटना। इनकी रिपोर्ट और जाँच होती है।"}],"E-105.1":[{"q":"How soon must a serious AEFI be notified?","qh":"गंभीर AEFI की सूचना कितनी जल्दी देनी चाहिए?","o":["Immediately, within 24 hours","Within one week","In the monthly report","Only if the child dies"],"oh":["तुरंत, 24 घंटे के अंदर","एक सप्ताह के अंदर","मासिक रिपोर्ट में","केवल बच्चे की मृत्यु होने पर"],"a":0,"x":"Serious/severe AEFI are notified immediately (within 24 hours) through the MO to the District Immunization Officer.","xh":"गंभीर AEFI की सूचना तुरंत (24 घंटे के अंदर) MO के ज़रिए ज़िला प्रतिरक्षण अधिकारी को दी जाती है।"}],"E-106.1":[{"q":"To whom is a serious AEFI case reported from the Sub-Centre?","qh":"उप-केंद्र से गंभीर AEFI की रिपोर्ट किसे की जाती है?","o":["The village pradhan","The PHC Medical Officer, who informs the District Immunization Officer","The vaccine manufacturer directly","No one, if the child recovers"],"oh":["ग्राम प्रधान को","PHC के चिकित्सा अधिकारी को, जो ज़िला प्रतिरक्षण अधिकारी को सूचित करते हैं","सीधे टीका निर्माता को","किसी को नहीं, अगर बच्चा ठीक हो जाए"],"a":1,"x":"The ANM/CHO informs the PHC MO, who notifies the District Immunization Officer; the case is then recorded and investigated.","xh":"ANM/CHO PHC चिकित्सा अधिकारी को बताती हैं, जो ज़िला प्रतिरक्षण अधिकारी को सूचित करते हैं; फिर मामला दर्ज और जाँचा जाता है।"}],"E-108.1":[{"q":"Which of these prevents an immunisation-error reaction?","qh":"इनमें से कौन-सा टीकाकरण की गलती से होने वाली प्रतिक्रिया को रोकता है?","o":["Using the diluent supplied with the same vaccine by the same manufacturer","Using any sterile water as diluent","Re-using a syringe if it looks clean","Keeping reconstituted vaccine for the next day"],"oh":["उसी निर्माता द्वारा उसी टीके के साथ दिया गया डाइल्यूएंट इस्तेमाल करना","डाइल्यूएंट के रूप में कोई भी जीवाणुरहित पानी इस्तेमाल करना","साफ़ दिखे तो सिरिंज दोबारा इस्तेमाल करना","घोले गए टीके को अगले दिन के लिए रखना"],"a":0,"x":"Right vaccine, right diluent from the same manufacturer, right dose and route, a new AD syringe each time, and reconstituted vaccine discarded after 4 hours.","xh":"सही टीका, उसी निर्माता का सही डाइल्यूएंट, सही खुराक और तरीका, हर बार नई AD सिरिंज, और घोला गया टीका 4 घंटे बाद फेंकना।"}],"E-109.1":[{"q":"How is the breathing rate of a child with cough counted?","qh":"खाँसी वाले बच्चे की साँस दर कैसे गिनी जाती है?","o":["For 15 seconds and multiplied by 4","For one full minute while the child is calm","Only when the child is crying","Breathing is not counted for cough"],"oh":["15 सेकंड गिनकर 4 से गुणा","बच्चे के शांत रहने पर पूरे एक मिनट","केवल बच्चे के रोते समय","खाँसी में साँस नहीं गिनी जाती"],"a":1,"x":"Count breaths for one full minute with the child calm, and look for chest in-drawing.","xh":"बच्चे के शांत रहने पर पूरे एक मिनट साँस गिनें, और छाती धँसने को देखें।"}],"E-109.2":[{"q":"A child aged 1–5 years has a mid-upper arm circumference (MUAC) of 11 cm. What does this mean?","qh":"1–5 वर्ष के बच्चे की बाँह का घेरा (MUAC) 11 cm है। इसका क्या मतलब है?","o":["Normal nutrition","Severe acute malnutrition (SAM) — refer","Overweight","Mild malnutrition — no action needed"],"oh":["सामान्य पोषण","गंभीर तीव्र कुपोषण (SAM) — रेफर करें","अधिक वज़न","हल्का कुपोषण — कोई कार्रवाई नहीं"],"a":1,"x":"MUAC below 11.5 cm in a child 6–59 months is SAM; refer to the NRC or manage as per the SAM protocol.","xh":"6–59 महीने के बच्चे में 11.5 cm से कम MUAC SAM है; NRC रेफर करें या SAM प्रोटोकॉल के अनुसार प्रबंधन करें।"}],"E-109.3":[{"q":"In a child with diarrhoea, the skin pinch on the abdomen goes back very slowly (more than 2 seconds). What does this show?","qh":"दस्त वाले बच्चे के पेट की त्वचा चुटकी से उठाने पर बहुत धीरे (2 सेकंड से अधिक में) वापस जाती है। यह क्या दर्शाता है?","o":["No dehydration","Some dehydration","Severe dehydration","Malnutrition only"],"oh":["पानी की कमी नहीं","कुछ पानी की कमी","गंभीर पानी की कमी","केवल कुपोषण"],"a":2,"x":"Skin pinch going back very slowly (over 2 seconds), with lethargy, sunken eyes or inability to drink, means severe dehydration — refer urgently, giving ORS on the way.","xh":"त्वचा का बहुत धीरे (2 सेकंड से अधिक) लौटना, सुस्ती, धँसी आँखें या पी न पाना गंभीर पानी की कमी है — रास्ते में ORS देते हुए तुरंत रेफर करें।"}],"E-110.2":[{"q":"A child aged 2 to 12 months has cough. From what breathing rate is it \"fast breathing\"?","qh":"2 से 12 महीने के बच्चे को खाँसी है। कितनी साँस दर से \"तेज़ साँस\" मानी जाती है?","o":["30 or more per minute","40 or more per minute","50 or more per minute","60 or more per minute"],"oh":["30 या अधिक प्रति मिनट","40 या अधिक प्रति मिनट","50 या अधिक प्रति मिनट","60 या अधिक प्रति मिनट"],"a":2,"x":"Fast breathing: 50 or more per minute at 2–12 months; 40 or more at 12 months–5 years.","xh":"तेज़ साँस: 2–12 महीने में 50 या अधिक प्रति मिनट; 12 महीने–5 वर्ष में 40 या अधिक।"}],"E-111.1":[{"q":"A 1-year-old child has diarrhoea without dehydration. What is the correct treatment with ORS?","qh":"1 वर्ष के बच्चे को बिना पानी की कमी के दस्त है। ORS के साथ सही उपचार क्या है?","o":["Antibiotic for every case","Zinc 20 mg daily for 14 days, with ORS and continued feeding","Zinc for 3 days only","Stop breastfeeding until diarrhoea stops"],"oh":["हर मामले में एंटीबायोटिक","14 दिन तक रोज़ ज़िंक 20 mg, ORS और खाना जारी रखते हुए","केवल 3 दिन ज़िंक","दस्त रुकने तक स्तनपान बंद करें"],"a":1,"x":"ORS plus zinc for 14 days — 10 mg a day for 2–6 months, 20 mg a day above 6 months — and continued feeding. Antibiotics only for blood in stool or as per protocol.","xh":"ORS और 14 दिन ज़िंक — 2–6 महीने में रोज़ 10 mg, 6 महीने से ऊपर रोज़ 20 mg — और खाना जारी रखें। एंटीबायोटिक केवल टट्टी में खून होने पर या प्रोटोकॉल के अनुसार।"}],"E-112.1":[{"q":"A child has cough and cold, no fast breathing and no chest in-drawing. What is the right care?","qh":"बच्चे को खाँसी-ज़ुकाम है, न तेज़ साँस है न छाती धँसती है। सही देखभाल क्या है?","o":["Antibiotic for 5 days","Home care: soothe the throat, keep feeding, paracetamol for fever, and return if breathing becomes fast or difficult","Refer to the district hospital","Stop all feeding"],"oh":["5 दिन एंटीबायोटिक","घर पर देखभाल: गले को आराम, खाना जारी रखें, बुखार पर पैरासिटामोल, और साँस तेज़ या कठिन हो तो वापस आएँ","ज़िला अस्पताल रेफर करें","सारा खाना बंद करें"],"a":1,"x":"Cough or cold without fast breathing or chest in-drawing is \"no pneumonia\": no antibiotic; home care and advice on when to return.","xh":"तेज़ साँस या छाती धँसे बिना खाँसी-ज़ुकाम \"निमोनिया नहीं\" है: कोई एंटीबायोटिक नहीं; घर पर देखभाल और कब लौटना है, इसकी सलाह।"}],"A-008.1":[{"q":"What IFA supplementation is given to adolescents (10–19 years) under Anemia Mukt Bharat?","qh":"एनीमिया मुक्त भारत में किशोरों (10–19 वर्ष) को कौन-सी IFA दी जाती है?","o":["One pink tablet daily","One blue tablet weekly","One red tablet daily","IFA syrup twice a week"],"oh":["रोज़ एक गुलाबी गोली","सप्ताह में एक नीली गोली","रोज़ एक लाल गोली","सप्ताह में दो बार IFA सिरप"],"a":1,"x":"Adolescents 10–19 years: one blue IFA tablet (60 mg iron + 500 mcg folic acid) once a week, plus deworming twice a year.","xh":"किशोर 10–19 वर्ष: सप्ताह में एक बार एक नीली IFA गोली (60 mg आयरन + 500 mcg फोलिक एसिड), और साल में दो बार कृमि-नाशक।"}],"A-010.4":[{"q":"After an abortion, when can a woman become pregnant again if she does not use contraception?","qh":"गर्भपात के बाद, गर्भनिरोधक न लेने पर महिला फिर से कब गर्भवती हो सकती है?","o":["Not for 6 months","As early as about 2 weeks, so contraception should start right away","Only after her periods are regular for 3 months","Not for a year"],"oh":["6 महीने तक नहीं","लगभग 2 सप्ताह में ही, इसलिए गर्भनिरोधक तुरंत शुरू होना चाहिए","केवल 3 महीने नियमित मासिक धर्म के बाद","एक साल तक नहीं"],"a":1,"x":"Fertility can return within about two weeks of an abortion, so most methods can be started immediately.","xh":"गर्भपात के लगभग दो सप्ताह में ही गर्भधारण क्षमता लौट सकती है, इसलिए ज़्यादातर तरीके तुरंत शुरू किए जा सकते हैं।"}],"E-116.1":[{"q":"Which of these is a LIMITING (permanent) method of family planning?","qh":"इनमें से कौन-सा परिवार नियोजन का स्थायी (लिमिटिंग) तरीका है?","o":["Condom","IUCD","Female or male sterilisation","Injectable MPA (Antara)"],"oh":["कंडोम","IUCD","महिला या पुरुष नसबंदी","इंजेक्शन MPA (अंतरा)"],"a":2,"x":"Sterilisation (tubectomy, vasectomy) is a limiting method; condoms, pills, IUCD and injectables are spacing methods.","xh":"नसबंदी (महिला, पुरुष) स्थायी तरीका है; कंडोम, गोलियाँ, IUCD और इंजेक्शन अंतराल के तरीके हैं।"}],"E-117.1":[{"q":"In the BRAIDED approach to family planning counselling, what does \"R\" stand for?","qh":"परिवार नियोजन परामर्श के BRAIDED तरीके में \"R\" का क्या अर्थ है?","o":["Referral","Risks of the method","Registration","Records"],"oh":["रेफरल","तरीके के जोखिम","पंजीकरण","रिकॉर्ड"],"a":1,"x":"BRAIDED: Benefits, Risks, Alternatives, Inquiries, Decision to withdraw, Explanation of the method, Documentation (the A also covers the consequence of method failure).","xh":"BRAIDED: लाभ (Benefits), जोखिम (Risks), विकल्प (Alternatives), पूछताछ (Inquiries), छोड़ने का निर्णय (Decision), तरीके की व्याख्या (Explanation), दस्तावेज़ (Documentation)।"}],"E-118.1":[{"q":"Who are eligible couples for spacing methods?","qh":"अंतराल के तरीकों के लिए योग्य दंपत्ति कौन हैं?","o":["Unmarried girls aged 10–19","Married couples where the woman is 15–49 years","Only couples with three children","Only women above 35"],"oh":["10–19 वर्ष की अविवाहित लड़कियाँ","विवाहित दंपत्ति जिनमें महिला 15–49 वर्ष की हो","केवल तीन बच्चों वाले दंपत्ति","केवल 35 वर्ष से ऊपर की महिलाएँ"],"a":1,"x":"An eligible couple is a currently married couple in which the wife is 15–49 years old.","xh":"योग्य दंपत्ति वह विवाहित दंपत्ति है जिसमें पत्नी की आयु 15–49 वर्ष हो।"}],"E-119.1":[{"q":"Which oral contraceptive is NON-hormonal?","qh":"कौन-सी गर्भनिरोधक गोली हार्मोन-रहित है?","o":["Mala-N","Chhaya (Centchroman)","Emergency contraceptive pill","All are hormonal"],"oh":["माला-N","छाया (सेंटक्रोमैन)","आपातकालीन गर्भनिरोधक गोली","सभी हार्मोनल हैं"],"a":1,"x":"Chhaya (Centchroman) is a non-steroidal, non-hormonal weekly pill; Mala-N is a combined hormonal pill; the ECP is levonorgestrel.","xh":"छाया (सेंटक्रोमैन) हार्मोन-रहित साप्ताहिक गोली है; माला-N संयुक्त हार्मोनल गोली है; ECP लेवोनोर्जेस्ट्रेल है।"}],"E-119.2":[{"q":"How is Chhaya (Centchroman) taken?","qh":"छाया (सेंटक्रोमैन) कैसे ली जाती है?","o":["One tablet daily","Twice a week for the first 3 months, then once a week","Once a month","Only after intercourse"],"oh":["रोज़ एक गोली","पहले 3 महीने सप्ताह में दो बार, फिर सप्ताह में एक बार","महीने में एक बार","केवल संबंध के बाद"],"a":1,"x":"First pill on the first day of the period, then twice a week for 3 months, then once a week on the same day.","xh":"पहली गोली मासिक धर्म के पहले दिन, फिर 3 महीने सप्ताह में दो बार, फिर हर सप्ताह उसी दिन एक बार।"},{"q":"Within how many hours of unprotected sex should the emergency contraceptive pill (ECP) be taken for it to work best?","qh":"असुरक्षित संबंध के कितने घंटों के अंदर आपातकालीन गर्भनिरोधक गोली (ECP) लेने पर वह सबसे अच्छा काम करती है?","o":["Within 72 hours, as soon as possible","Within 7 days","Only within 1 hour","Before the next period, any time"],"oh":["72 घंटे के अंदर, जितनी जल्दी हो सके","7 दिन के अंदर","केवल 1 घंटे के अंदर","अगले मासिक धर्म से पहले कभी भी"],"a":0,"x":"Levonorgestrel 1.5 mg as a single dose (one 1.5 mg tablet, or two 0.75 mg tablets together), as soon as possible and within 72 hours.","xh":"लेवोनोर्जेस्ट्रेल 1.5 mg एक खुराक में (एक 1.5 mg गोली, या दो 0.75 mg गोलियाँ एक साथ), जितनी जल्दी हो सके और 72 घंटे के अंदर।"}],"E-120.1":[{"q":"What is the \"no-touch\" technique in IUCD insertion?","qh":"IUCD लगाते समय \"नो-टच\" तकनीक क्या है?","o":["Not touching the woman at all during insertion","Loading the IUCD in its sterile pack and not letting the loaded IUCD or the inserter tip touch anything unsterile, including the vaginal walls","Inserting without gloves","Not using a speculum"],"oh":["लगाते समय महिला को बिल्कुल न छूना","IUCD को उसके जीवाणुरहित पैक में लोड करना और लोड की गई IUCD या इंसर्टर की नोक को किसी गैर-जीवाणुरहित चीज़ (योनि की दीवारों सहित) से न छूने देना","बिना दस्ताने के लगाना","स्पेकुलम का उपयोग न करना"],"a":1,"x":"No-touch: load the IUCD inside the sterile package and keep the loaded IUCD and inserter from touching any unsterile surface or the vaginal walls, to prevent infection.","xh":"नो-टच: IUCD को जीवाणुरहित पैक के अंदर लोड करें और संक्रमण से बचाने के लिए लोड की गई IUCD व इंसर्टर को किसी गैर-जीवाणुरहित सतह या योनि की दीवारों से न छूने दें।"}],"E-120.3":[{"q":"Who may insert an IUCD after a second-trimester abortion?","qh":"दूसरी तिमाही के गर्भपात के बाद IUCD कौन लगा सकता है?","o":["Any ANM","Only a trained Medical Officer","An ASHA","The CHO, at home"],"oh":["कोई भी ANM","केवल प्रशिक्षित चिकित्सा अधिकारी","आशा","CHO, घर पर"],"a":1,"x":"After a second-trimester abortion, IUCD insertion is done only by a trained Medical Officer.","xh":"दूसरी तिमाही के गर्भपात के बाद IUCD केवल प्रशिक्षित चिकित्सा अधिकारी लगाते हैं।"}],"E-121.2":[{"q":"How often is the injectable contraceptive MPA (Antara) given?","qh":"इंजेक्शन गर्भनिरोधक MPA (अंतरा) कितने अंतराल पर दिया जाता है?","o":["Every month","Every 3 months","Every 6 months","Once a year"],"oh":["हर महीने","हर 3 महीने","हर 6 महीने","साल में एक बार"],"a":1,"x":"MPA (150 mg IM, or the subcutaneous form) is repeated every 3 months; the next dose can be given up to 2 weeks early or 4 weeks late.","xh":"MPA (150 mg IM, या त्वचा के नीचे वाला रूप) हर 3 महीने पर दोहराया जाता है; अगली खुराक 2 सप्ताह पहले या 4 सप्ताह देर तक दी जा सकती है।"}],"E-122.1":[{"q":"Which client is eligible for female sterilisation?","qh":"महिला नसबंदी के लिए कौन योग्य है?","o":["An unmarried woman aged 20","A married woman aged 22–49 whose youngest child is at least 1 year old","A married woman aged 18 with one newborn","Any woman, on her husband's request alone"],"oh":["20 वर्ष की अविवाहित महिला","22–49 वर्ष की विवाहित महिला जिसका सबसे छोटा बच्चा कम से कम 1 वर्ष का हो","एक नवजात वाली 18 वर्ष की विवाहित महिला","कोई भी महिला, केवल पति के कहने पर"],"a":1,"x":"Eligible: married; woman 22–49 years (man 22–60 for vasectomy); at least one child older than 1 year; spouse not sterilised; free and informed consent of the client.","xh":"योग्य: विवाहित; महिला 22–49 वर्ष (पुरुष नसबंदी में 22–60); कम से कम एक बच्चा 1 वर्ष से बड़ा; पति/पत्नी की नसबंदी न हुई हो; व्यक्ति की स्वतंत्र और सूचित सहमति।"}],"E-123.1":[{"q":"When is the female sterilisation certificate issued?","qh":"महिला नसबंदी का प्रमाणपत्र कब दिया जाता है?","o":["On the day of surgery","One month after surgery or after the first period, whichever is earlier","After 6 months","After a semen test"],"oh":["ऑपरेशन के दिन","ऑपरेशन के एक महीने बाद या पहले मासिक धर्म के बाद, जो पहले हो","6 महीने बाद","वीर्य जाँच के बाद"],"a":1,"x":"The female sterilisation certificate is issued one month after surgery or after the first menstrual period, whichever is earlier.","xh":"महिला नसबंदी का प्रमाणपत्र ऑपरेशन के एक महीने बाद या पहले मासिक धर्म के बाद, जो पहले हो, दिया जाता है।"}],"E-123.2":[{"q":"When is a man considered sterile after vasectomy?","qh":"नसबंदी के बाद पुरुष को कब पूरी तरह सुरक्षित (स्टेराइल) माना जाता है?","o":["Immediately after the operation","When a semen test at 3 months shows no sperm","After one week","After 20 ejaculations, without any test"],"oh":["ऑपरेशन के तुरंत बाद","जब 3 महीने बाद वीर्य जाँच में शुक्राणु न मिलें","एक सप्ताह बाद","बिना जाँच के 20 बार स्खलन के बाद"],"a":1,"x":"Use condoms until semen analysis at 3 months shows no sperm; the certificate is issued then (up to 6 months if sperm are still seen).","xh":"3 महीने की वीर्य जाँच में शुक्राणु न मिलने तक कंडोम का उपयोग करें; तब प्रमाणपत्र दिया जाता है (शुक्राणु मिलते रहें तो 6 महीने तक)।"}],"E-029.1":[{"q":"Putting larvivorous fish (e.g. Gambusia, guppy) into ponds is which kind of mosquito control?","qh":"तालाबों में लार्वा खाने वाली मछली (जैसे गम्बूज़िया, गप्पी) डालना किस प्रकार का मच्छर नियंत्रण है?","o":["Chemical control","Biological control","Personal protection","Source reduction by drying"],"oh":["रासायनिक नियंत्रण","जैविक नियंत्रण","व्यक्तिगत सुरक्षा","सुखाकर स्रोत खत्म करना"],"a":1,"x":"Larvivorous fish eat mosquito larvae — biological control. Source reduction removes breeding water; larvicides and fogging are chemical control; nets and repellents are personal protection.","xh":"लार्वा खाने वाली मछली मच्छर के लार्वा खाती है — जैविक नियंत्रण। स्रोत खत्म करना पानी जमा न होने देना है; लार्वानाशी और फॉगिंग रासायनिक नियंत्रण है; मच्छरदानी और रिपेलेंट व्यक्तिगत सुरक्षा है।"}],"E-031.1":[{"q":"Within how long of detection should a confirmed malaria case start treatment?","qh":"पुष्टि हुए मलेरिया मामले में पता चलने के कितने समय के अंदर इलाज शुरू होना चाहिए?","o":["Within 24 hours","Within 1 week","After the slide result comes from the district","Only if fever lasts 7 days"],"oh":["24 घंटे के अंदर","1 सप्ताह के अंदर","ज़िले से स्लाइड का परिणाम आने के बाद","केवल 7 दिन बुखार रहने पर"],"a":0,"x":"Every confirmed case (RDT or slide) should get complete treatment within 24 hours of detection.","xh":"हर पुष्टि हुए मामले (RDT या स्लाइड) को पता चलने के 24 घंटे के अंदर पूरा इलाज मिलना चाहिए।"}],"E-031.2":[{"q":"What is the treatment for P. vivax malaria in a non-pregnant adult?","qh":"गैर-गर्भवती वयस्क में P. vivax मलेरिया का इलाज क्या है?","o":["ACT for 3 days only","Chloroquine for 3 days plus primaquine for 14 days","Primaquine single dose only","Paracetamol and rest"],"oh":["केवल 3 दिन ACT","3 दिन क्लोरोक्वीन और 14 दिन प्राइमाक्वीन","केवल प्राइमाक्वीन की एक खुराक","पैरासिटामोल और आराम"],"a":1,"x":"P. vivax: chloroquine 3 days + primaquine 0.25 mg/kg daily for 14 days. Primaquine is not given in pregnancy, to infants, or with G6PD deficiency. P. falciparum: ACT for 3 days plus a single dose of primaquine (with the same exclusions).","xh":"P. vivax: 3 दिन क्लोरोक्वीन + 14 दिन रोज़ प्राइमाक्वीन 0.25 mg/kg। प्राइमाक्वीन गर्भावस्था में, शिशुओं को, या G6PD कमी में नहीं दी जाती। P. falciparum: 3 दिन ACT और प्राइमाक्वीन की एक खुराक (इन्हीं अपवादों के साथ)।"}],"E-032.1":[{"q":"A malaria patient still has fever 48 hours after starting treatment, with repeated vomiting. What should be done?","qh":"इलाज शुरू होने के 48 घंटे बाद भी मलेरिया रोगी को बुखार है और बार-बार उल्टी हो रही है। क्या करना चाहिए?","o":["Continue the same tablets at home","Refer urgently — these are danger signs","Double the dose","Stop treatment"],"oh":["घर पर वही गोलियाँ जारी रखें","तुरंत रेफर करें — ये खतरे के संकेत हैं","खुराक दोगुनी करें","इलाज बंद करें"],"a":1,"x":"Fever after 48 hours of treatment, persistent vomiting, altered sensorium, convulsions, bleeding, jaundice or very low urine are signs of severe malaria or failure — refer.","xh":"इलाज के 48 घंटे बाद बुखार, लगातार उल्टी, बेहोशी, दौरे, खून बहना, पीलिया या बहुत कम पेशाब गंभीर मलेरिया या इलाज विफलता के संकेत हैं — रेफर करें।"}],"E-033.2":[{"q":"Which medicine should NOT be given for fever in suspected dengue?","qh":"संदिग्ध डेंगू में बुखार के लिए कौन-सी दवा नहीं देनी चाहिए?","o":["Paracetamol","Aspirin or ibuprofen (NSAIDs)","ORS","Plenty of oral fluids"],"oh":["पैरासिटामोल","एस्पिरिन या आइबुप्रोफ़ेन (NSAIDs)","ORS","मुँह से भरपूर तरल"],"a":1,"x":"In dengue use paracetamol and fluids only; aspirin and other NSAIDs increase the risk of bleeding.","xh":"डेंगू में केवल पैरासिटामोल और तरल दें; एस्पिरिन और अन्य NSAIDs से खून बहने का खतरा बढ़ता है।"}],"E-036.1":[{"q":"Which sign suggests kala-azar in an endemic area?","qh":"स्थानिक क्षेत्र में कौन-सा संकेत काला-अज़ार की ओर इशारा करता है?","o":["Fever for more than 2 weeks with an enlarged spleen, not responding to antimalarials","Fever for one day with a rash","Joint pain after a mosquito bite","Swelling of one leg for years"],"oh":["2 सप्ताह से अधिक बुखार, बढ़ी हुई तिल्ली, मलेरिया की दवा से ठीक न होना","एक दिन बुखार और दाने","मच्छर काटने के बाद जोड़ों में दर्द","वर्षों से एक पैर में सूजन"],"a":0,"x":"Kala-azar: fever for 2 weeks or more with splenomegaly in an endemic area, not responding to antimalarials — refer for rK39 test. (Long-standing leg swelling suggests filariasis; joint pain after fever suggests chikungunya.)","xh":"काला-अज़ार: स्थानिक क्षेत्र में 2 सप्ताह या अधिक बुखार और बढ़ी तिल्ली, मलेरिया की दवा से ठीक न हो — rK39 जाँच के लिए रेफर करें। (लंबे समय से पैर की सूजन फाइलेरिया, बुखार के बाद जोड़ों का दर्द चिकनगुनिया दर्शाता है।)"}],"A-014.1":[{"q":"Who should be identified as a presumptive TB case?","qh":"किसे संभावित (प्रिज़म्प्टिव) TB मामले के रूप में पहचाना जाना चाहिए?","o":["Anyone with a cough of 2 weeks or more, fever, weight loss, night sweats or blood in sputum","Only people with blood in sputum","Anyone with a cold for 2 days","Only people above 60"],"oh":["2 सप्ताह या अधिक खाँसी, बुखार, वज़न घटना, रात में पसीना या बलगम में खून वाला कोई भी व्यक्ति","केवल बलगम में खून वाले लोग","2 दिन से ज़ुकाम वाला कोई भी","केवल 60 वर्ष से ऊपर के लोग"],"a":0,"x":"Presumptive TB: cough of 2 weeks or more, fever, significant weight loss, night sweats, or haemoptysis (any one) — send for sputum test (NAAT/microscopy).","xh":"संभावित TB: 2 सप्ताह या अधिक खाँसी, बुखार, काफ़ी वज़न घटना, रात में पसीना, या बलगम में खून (कोई भी एक) — बलगम जाँच (NAAT/माइक्रोस्कोपी) के लिए भेजें।"}],"E-039.1":[{"q":"After a TB patient completes treatment, when are follow-up checks done?","qh":"TB रोगी का इलाज पूरा होने के बाद फ़ॉलो-अप जाँच कब होती है?","o":["Never","At 6, 12, 18 and 24 months","Only once at 1 month","Every week for a year"],"oh":["कभी नहीं","6, 12, 18 और 24 महीने पर","केवल 1 महीने पर एक बार","एक साल तक हर सप्ताह"],"a":1,"x":"NTEP follows patients up for 2 years after treatment — at 6, 12, 18 and 24 months — to catch relapse early.","xh":"NTEP इलाज के बाद 2 वर्ष तक — 6, 12, 18 और 24 महीने पर — फ़ॉलो-अप करता है ताकि दोबारा बीमारी जल्दी पकड़ी जा सके।"}],"A-016.1":[{"q":"What is the main sign of suspected leprosy?","qh":"संदिग्ध कुष्ठ रोग का मुख्य संकेत क्या है?","o":["An itchy red rash that comes and goes","A pale or reddish skin patch with definite loss of sensation","Hair loss on the scalp","Dry skin in winter"],"oh":["आता-जाता खुजली वाला लाल दाना","हल्का या लालिमा लिए त्वचा का धब्बा जिसमें निश्चित रूप से सुन्नपन हो","सिर के बाल झड़ना","सर्दियों में रूखी त्वचा"],"a":1,"x":"A hypopigmented or reddish patch with definite loss of sensation, or thickened nerves with weakness or numbness, suggests leprosy — refer for diagnosis; MDT is free.","xh":"हल्का या लाल धब्बा जिसमें निश्चित सुन्नपन हो, या मोटी नसें और कमज़ोरी या सुन्नपन, कुष्ठ रोग दर्शाते हैं — जाँच के लिए रेफर करें; MDT मुफ़्त है।"}],"E-041.2":[{"q":"How is the sensation in a suspected leprosy patch tested?","qh":"संदिग्ध कुष्ठ धब्बे में संवेदना की जाँच कैसे की जाती है?","o":["With a needle prick until it bleeds","Touch the patch lightly (pen tip or cotton wisp) first with eyes open, then eyes closed, and ask the person to point","By applying hot water","By looking only, without touching"],"oh":["सुई चुभाकर, खून आने तक","धब्बे को हल्के से (पेन की नोक या रुई) छुएँ, पहले आँखें खुली रखकर फिर बंद कराकर, और व्यक्ति से जगह बताने को कहें","गर्म पानी लगाकर","केवल देखकर, बिना छुए"],"a":1,"x":"Show the test with eyes open first, then touch the patch and normal skin with eyes closed; if the person cannot feel the touch on the patch, sensation is lost.","xh":"पहले आँखें खुली रखकर जाँच दिखाएँ, फिर आँखें बंद कराकर धब्बे और सामान्य त्वचा को छुएँ; धब्बे पर छूना महसूस न हो तो संवेदना खत्म है।"}],"E-047.1":[{"q":"Which of these is reported weekly on the IDSP S-form?","qh":"इनमें से क्या IDSP S-फ़ॉर्म पर साप्ताहिक रिपोर्ट किया जाता है?","o":["Acute flaccid paralysis in a child under 15","A healed fracture","A routine ANC visit","Vaccination given"],"oh":["15 वर्ष से कम बच्चे में अचानक ढीला लकवा (AFP)","ठीक हुआ फ्रैक्चर","नियमित ANC जाँच","दिया गया टीका"],"a":0,"x":"S-form syndromes: fever, cough under 2 weeks, acute flaccid paralysis, diarrhoea (3 or more loose stools in 24 hours), jaundice, and any unusual event or death.","xh":"S-फ़ॉर्म लक्षण-समूह: बुखार, 2 सप्ताह से कम की खाँसी, AFP, दस्त (24 घंटे में 3 या अधिक पतले दस्त), पीलिया, और कोई असामान्य घटना या मृत्यु।"}],"E-051.1":[{"q":"Within how long of birth should the Hepatitis B birth dose be given?","qh":"हेपेटाइटिस B की जन्म-खुराक जन्म के कितने समय के अंदर दी जानी चाहिए?","o":["Within 24 hours","Within 6 weeks","At 9 months","At 1 year"],"oh":["24 घंटे के अंदर","6 सप्ताह के अंदर","9 महीने पर","1 वर्ष पर"],"a":0,"x":"The Hepatitis B birth dose is given as early as possible, within 24 hours of birth, to prevent mother-to-child transmission.","xh":"हेपेटाइटिस B की जन्म-खुराक जितनी जल्दी हो सके, जन्म के 24 घंटे के अंदर दी जाती है, ताकि माँ से बच्चे में संक्रमण न हो।"}],"E-052.1":[{"q":"From what age is the CBAC form filled for population-based NCD screening?","qh":"जनसंख्या-आधारित NCD जाँच के लिए CBAC फ़ॉर्म किस उम्र से भरा जाता है?","o":["18 years","30 years","45 years","60 years"],"oh":["18 वर्ष","30 वर्ष","45 वर्ष","60 वर्ष"],"a":1,"x":"Everyone aged 30 and above fills the CBAC form and is screened for hypertension, diabetes and common cancers.","xh":"30 वर्ष और उससे अधिक आयु का हर व्यक्ति CBAC फ़ॉर्म भरता है और उच्च रक्तचाप, मधुमेह और सामान्य कैंसर की जाँच कराता है।"}],"E-053.1":[{"q":"At screening, which BP reading means the person is suspected to have hypertension and is referred to the MO?","qh":"जाँच में कौन-सी BP रीडिंग पर व्यक्ति को उच्च रक्तचाप का संदिग्ध मानकर MO के पास भेजा जाता है?","o":["120/80 mm Hg","130/85 mm Hg","140/90 mm Hg or higher","Only above 180/110 mm Hg"],"oh":["120/80 mm Hg","130/85 mm Hg","140/90 mm Hg या अधिक","केवल 180/110 mm Hg से ऊपर"],"a":2,"x":"Systolic 140 or more and/or diastolic 90 or more is suspected hypertension; confirm and start treatment through the MO.","xh":"सिस्टोलिक 140 या अधिक और/या डायस्टोलिक 90 या अधिक संदिग्ध उच्च रक्तचाप है; MO के माध्यम से पुष्टि और इलाज शुरू करें।"}],"E-057.1":[{"q":"At screening, what random blood sugar means the person must be referred to confirm diabetes?","qh":"जाँच में कितनी रैंडम ब्लड शुगर पर व्यक्ति को मधुमेह की पुष्टि के लिए रेफर करना ज़रूरी है?","o":["100 mg/dl or more","140 mg/dl or more","200 mg/dl or more only","300 mg/dl or more only"],"oh":["100 mg/dl या अधिक","140 mg/dl या अधिक","केवल 200 mg/dl या अधिक","केवल 300 mg/dl या अधिक"],"a":1,"x":"Random capillary blood glucose of 140 mg/dl or more is screen-positive and is referred for confirmation.","xh":"140 mg/dl या अधिक रैंडम कैपिलरी ब्लड ग्लूकोज़ स्क्रीन-पॉज़िटिव है और पुष्टि के लिए रेफर किया जाता है।"}],"E-060.2":[{"q":"What waist size shows abdominal obesity in an Indian woman?","qh":"भारतीय महिला में कितनी कमर का नाप पेट का मोटापा दर्शाता है?","o":["70 cm or more","80 cm or more","100 cm or more","Waist size does not matter"],"oh":["70 cm या अधिक","80 cm या अधिक","100 cm या अधिक","कमर का नाप मायने नहीं रखता"],"a":1,"x":"Abdominal obesity: waist 80 cm or more in women and 90 cm or more in men (also scored on the CBAC form).","xh":"पेट का मोटापा: महिलाओं में कमर 80 cm या अधिक और पुरुषों में 90 cm या अधिक (CBAC फ़ॉर्म में भी अंक मिलते हैं)।"}],"E-063.1":[{"q":"Which symptom should make a woman be referred for cervical cancer check-up?","qh":"किस लक्षण पर महिला को गर्भाशय-मुख कैंसर की जाँच के लिए रेफर करना चाहिए?","o":["Bleeding after menopause or after intercourse","Regular periods every 28 days","Mild back pain after work","White discharge only during pregnancy"],"oh":["रजोनिवृत्ति के बाद या संबंध के बाद खून आना","हर 28 दिन पर नियमित मासिक धर्म","काम के बाद हल्का कमर दर्द","केवल गर्भावस्था में सफ़ेद पानी"],"a":0,"x":"Bleeding between periods, after intercourse or after menopause, and foul-smelling discharge are warning signs of cervical cancer.","xh":"मासिक धर्म के बीच, संबंध के बाद या रजोनिवृत्ति के बाद खून आना, और बदबूदार स्राव गर्भाशय-मुख कैंसर के चेतावनी संकेत हैं।"}],"E-064.1":[{"q":"Which of these is a warning sign of breast cancer?","qh":"इनमें से कौन-सा स्तन कैंसर का चेतावनी संकेत है?","o":["A painless lump in the breast or armpit","Breast fullness before periods","Milk while breastfeeding","Both breasts slightly different in size since puberty"],"oh":["स्तन या बगल में बिना दर्द की गाँठ","मासिक धर्म से पहले स्तन में भारीपन","स्तनपान के समय दूध","किशोरावस्था से दोनों स्तनों में थोड़ा अंतर"],"a":0,"x":"A lump in the breast or armpit, skin puckering or dimpling, nipple pulled in, or bloody nipple discharge needs referral.","xh":"स्तन या बगल में गाँठ, त्वचा में सिकुड़न या गड्ढे, निप्पल अंदर खिंचना, या निप्पल से खून आना — रेफर करें।"}],"E-065.1":[{"q":"Which of these in the mouth should be referred as possible oral cancer?","qh":"मुँह में इनमें से किसे संभावित मुँह के कैंसर के रूप में रेफर करना चाहिए?","o":["A white or red patch, or an ulcer that has not healed for more than 2 weeks","A mouth ulcer that healed in 3 days","Bad breath after eating onion","A loose milk tooth in a child"],"oh":["सफ़ेद या लाल धब्बा, या 2 सप्ताह से अधिक समय से न भरने वाला छाला","3 दिन में भरा मुँह का छाला","प्याज़ खाने के बाद मुँह की बदबू","बच्चे का हिलता दूध का दाँत"],"a":0,"x":"White (leukoplakia) or red patches, a non-healing ulcer, a lump, or difficulty opening the mouth — especially in tobacco users — are referred.","xh":"सफ़ेद या लाल धब्बे, न भरने वाला छाला, गाँठ, या मुँह खोलने में कठिनाई — खासकर तंबाकू सेवन करने वालों में — रेफर करें।"}],"E-066.1":[{"q":"How is cervical cancer screened at the primary level?","qh":"प्राथमिक स्तर पर गर्भाशय-मुख कैंसर की जाँच कैसे होती है?","o":["By X-ray","By Visual Inspection with Acetic acid (VIA), for women aged 30–65","By a blood test","By ultrasound of the abdomen"],"oh":["एक्स-रे से","एसिटिक एसिड से दृश्य जाँच (VIA) द्वारा, 30–65 वर्ष की महिलाओं में","खून की जाँच से","पेट के अल्ट्रासाउंड से"],"a":1,"x":"VIA with 3–5% acetic acid by a trained provider, for women 30–65 years, with privacy.","xh":"प्रशिक्षित व्यक्ति द्वारा 3–5% एसिटिक एसिड से VIA, 30–65 वर्ष की महिलाओं में, गोपनीयता के साथ।"}],"E-066.4":[{"q":"When is VIA positive?","qh":"VIA कब पॉज़िटिव मानी जाती है?","o":["The cervix looks pink and uniform","A clear, dense white (acetowhite) area appears near the transformation zone about a minute after applying acetic acid","Any discharge is seen","The woman feels a burning sensation"],"oh":["गर्भाशय-मुख गुलाबी और एक-सा दिखे","एसिटिक एसिड लगाने के लगभग एक मिनट बाद ट्रांसफ़ॉर्मेशन ज़ोन के पास साफ़, गाढ़ा सफ़ेद हिस्सा दिखे","कोई भी स्राव दिखे","महिला को जलन महसूस हो"],"a":1,"x":"A well-defined dense acetowhite area touching the squamo-columnar junction is VIA positive; refer for colposcopy.","xh":"स्क्वैमो-कॉलमनर जंक्शन को छूता साफ़, गाढ़ा सफ़ेद हिस्सा VIA पॉज़िटिव है; कोल्पोस्कोपी के लिए रेफर करें।"}],"E-069.2":[{"q":"What are the \"5 A's\" of tobacco cessation, in order?","qh":"तंबाकू छुड़ाने के \"5 A\" क्रम से क्या हैं?","o":["Ask, Advise, Assess, Assist, Arrange","Advise, Arrest, Assist, Admit, Approve","Ask, Admit, Avoid, Accept, Apply","Assess, Avoid, Allow, Advise, Act"],"oh":["पूछें, सलाह दें, आकलन करें, सहायता करें, व्यवस्था करें (Ask, Advise, Assess, Assist, Arrange)","Advise, Arrest, Assist, Admit, Approve","Ask, Admit, Avoid, Accept, Apply","Assess, Avoid, Allow, Advise, Act"],"a":0,"x":"Ask about tobacco use, Advise to quit clearly and personally, Assess willingness, Assist the attempt, Arrange follow-up.","xh":"तंबाकू के बारे में पूछें, स्पष्ट और व्यक्तिगत रूप से छोड़ने की सलाह दें, इच्छा का आकलन करें, कोशिश में सहायता करें, फ़ॉलो-अप की व्यवस्था करें।"}],"A-034.3":[{"q":"Which babies need eye screening for retinopathy of prematurity (ROP)?","qh":"किन शिशुओं की प्रीमैच्योरिटी रेटिनोपैथी (ROP) के लिए आँखों की जाँच ज़रूरी है?","o":["All babies at 1 year","Babies born before 34 weeks or weighing under 1750 g, by 4 weeks of age","Only babies with red eyes","Only babies who were given phototherapy"],"oh":["1 वर्ष पर सभी शिशु","34 सप्ताह से पहले जन्मे या 1750 g से कम वज़न वाले शिशु, 4 सप्ताह की उम्र तक","केवल लाल आँखों वाले शिशु","केवल फ़ोटोथेरेपी पाए शिशु"],"a":1,"x":"Preterm babies (before 34 weeks) or under 1750 g — and sicker babies up to 36 weeks — are screened by an eye specialist by day 30 of life. Untreated ROP causes blindness.","xh":"34 सप्ताह से पहले जन्मे या 1750 g से कम वज़न वाले शिशुओं (और 36 सप्ताह तक के बीमार शिशुओं) की आँख-विशेषज्ञ द्वारा जीवन के 30वें दिन तक जाँच होती है। बिना इलाज ROP से अंधापन होता है।"}],"E-006.1":[{"q":"An elderly person complains of slowly increasing blurred, cloudy vision and glare in sunlight. What is the likely cause?","qh":"एक बुज़ुर्ग धीरे-धीरे बढ़ते धुंधलेपन और धूप में चकाचौंध की शिकायत करते हैं। संभावित कारण क्या है?","o":["Conjunctivitis","Cataract","Stye","Allergy"],"oh":["आँख आना (कंजंक्टिवाइटिस)","मोतियाबिंद","गुहेरी","एलर्जी"],"a":1,"x":"Cataract: gradual painless blurring, glare and halos, frequent change of glasses — refer for surgery.","xh":"मोतियाबिंद: धीरे-धीरे बिना दर्द धुंधलापन, चकाचौंध और रोशनी के घेरे, बार-बार चश्मा बदलना — ऑपरेशन के लिए रेफर करें।"}],"E-007.1":[{"q":"A child has Bitot's spots and night blindness. What is the cause?","qh":"बच्चे की आँख में बिटॉट स्पॉट और रतौंधी है। इसका कारण क्या है?","o":["Vitamin A deficiency","Iron deficiency","Too much screen time","Allergy to dust"],"oh":["विटामिन A की कमी","आयरन की कमी","ज़्यादा स्क्रीन देखना","धूल से एलर्जी"],"a":0,"x":"Bitot's spots and night blindness are signs of xerophthalmia (vitamin A deficiency); give vitamin A as per protocol and refer.","xh":"बिटॉट स्पॉट और रतौंधी ज़ेरोफ़्थैल्मिया (विटामिन A की कमी) के संकेत हैं; प्रोटोकॉल के अनुसार विटामिन A दें और रेफर करें।"}],"E-007.2":[{"q":"Lime or acid has splashed into a person's eye. What is the first thing to do?","qh":"किसी की आँख में चूना या तेज़ाब गिर गया है। सबसे पहले क्या करें?","o":["Put a bandage on the eye and refer","Wash the eye with plenty of clean water for at least 15–20 minutes, then refer","Put ghee or oil in the eye","Rub the eye to remove it"],"oh":["आँख पर पट्टी बाँधकर रेफर करें","कम से कम 15–20 मिनट भरपूर साफ़ पानी से आँख धोएँ, फिर रेफर करें","आँख में घी या तेल डालें","निकालने के लिए आँख मलें"],"a":1,"x":"Chemical injury: immediate, continuous irrigation with clean water for at least 15–20 minutes, then urgent referral.","xh":"रासायनिक चोट: तुरंत, लगातार कम से कम 15–20 मिनट साफ़ पानी से धोएँ, फिर तुरंत रेफर करें।"}],"E-008.1":[{"q":"At what distance is a Snellen chart read for distance vision?","qh":"दूर की नज़र के लिए स्नेलेन चार्ट कितनी दूरी से पढ़ा जाता है?","o":["1 metre","3 metres","6 metres","10 metres"],"oh":["1 मीटर","3 मीटर","6 मीटर","10 मीटर"],"a":2,"x":"The Snellen chart is read at 6 metres, one eye at a time; normal vision is 6/6.","xh":"स्नेलेन चार्ट 6 मीटर से, एक-एक आँख से पढ़ा जाता है; सामान्य नज़र 6/6 है।"}],"E-012.1":[{"q":"A patient has ear discharge and a suspected perforated eardrum. What should NOT be done?","qh":"रोगी के कान से स्राव है और कान का पर्दा फटा होने का संदेह है। क्या नहीं करना चाहिए?","o":["Keep the ear dry","Syringe (wash) the ear","Refer to the ENT specialist","Dry-mop the ear with a clean wick"],"oh":["कान सूखा रखें","कान में पिचकारी से पानी डालें (सिरिंजिंग)","ENT विशेषज्ञ को रेफर करें","साफ़ बत्ती से कान सुखाएँ"],"a":1,"x":"Never syringe an ear with discharge or a perforated drum; keep it dry, dry-mop, and refer.","xh":"स्राव वाले या फटे पर्दे वाले कान में कभी पिचकारी न करें; कान सूखा रखें, बत्ती से सुखाएँ, और रेफर करें।"}],"E-014.2":[{"q":"What is the first aid for a nose bleed?","qh":"नाक से खून आने पर प्राथमिक उपचार क्या है?","o":["Tilt the head back and lie flat","Sit up, lean forward, and pinch the soft part of the nose for 10 minutes","Put cotton soaked in oil deep in the nose","Blow the nose hard"],"oh":["सिर पीछे झुकाकर लेट जाएँ","सीधे बैठें, आगे झुकें, और नाक के मुलायम हिस्से को 10 मिनट दबाएँ","तेल में भीगी रुई नाक में गहराई तक डालें","ज़ोर से नाक साफ़ करें"],"a":1,"x":"Sit up and lean forward, pinch the soft part of the nose for 10 minutes, breathe through the mouth; refer if bleeding does not stop.","xh":"सीधे बैठकर आगे झुकें, नाक के मुलायम हिस्से को 10 मिनट दबाएँ, मुँह से साँस लें; खून न रुके तो रेफर करें।"}],"E-017.1":[{"q":"An adult is choking and cannot speak or cough. Where is pressure applied in the Heimlich manoeuvre?","qh":"एक वयस्क का गला घुट रहा है, वह बोल या खाँस नहीं पा रहा। हेमलिच विधि में दबाव कहाँ दिया जाता है?","o":["On the chest over the breastbone","Upward thrusts on the abdomen between the navel and the rib cage","On the back of the neck","On the lower abdomen below the navel"],"oh":["छाती की हड्डी पर","नाभि और पसलियों के बीच पेट पर ऊपर की ओर झटके","गर्दन के पीछे","नाभि के नीचे पेट पर"],"a":1,"x":"Stand behind, place a fist above the navel and below the rib cage, and give quick inward-and-upward thrusts until the object comes out. (Infants: back blows and chest thrusts instead.)","xh":"पीछे खड़े होकर नाभि के ऊपर और पसलियों के नीचे मुट्ठी रखें, और चीज़ निकलने तक अंदर-ऊपर की ओर तेज़ झटके दें। (शिशुओं में पीठ पर थपकी और छाती पर दबाव।)"}],"E-021.1":[{"q":"A child's permanent front tooth has been knocked out. How should the tooth be carried to the dentist?","qh":"बच्चे का स्थायी आगे का दाँत टूटकर निकल गया है। दाँत को दंत-चिकित्सक तक कैसे ले जाएँ?","o":["Wrapped in dry tissue paper","In clean milk (or the child's own saliva), and reach the dentist as soon as possible","After scrubbing it clean with a brush","It cannot be saved — throw it away"],"oh":["सूखे टिशू पेपर में लपेटकर","साफ़ दूध (या बच्चे की अपनी लार) में, और जितनी जल्दी हो सके दंत-चिकित्सक तक पहुँचें","ब्रश से रगड़कर साफ़ करने के बाद","बचाया नहीं जा सकता — फेंक दें"],"a":1,"x":"Hold the tooth by the crown, do not scrub the root, keep it moist in milk or saliva, and reach a dentist quickly (ideally within an hour) for re-implantation.","xh":"दाँत को ऊपर के हिस्से से पकड़ें, जड़ न रगड़ें, दूध या लार में नम रखें, और दोबारा लगवाने के लिए जल्दी (हो सके तो एक घंटे के अंदर) दंत-चिकित्सक तक पहुँचें।"}],"E-025.2":[{"q":"Which tool does the CHO use to screen for depression?","qh":"अवसाद (डिप्रेशन) की जाँच के लिए CHO कौन-सा टूल उपयोग करती हैं?","o":["CBAC","PHQ-9 (PHQ-2 first)","Snellen chart","Partograph"],"oh":["CBAC","PHQ-9 (पहले PHQ-2)","स्नेलेन चार्ट","पार्टोग्राफ़"],"a":1,"x":"PHQ-2/PHQ-9 is used for depression; AUDIT for alcohol use; other standard tools for dementia, epilepsy and suicide risk.","xh":"अवसाद के लिए PHQ-2/PHQ-9; शराब के लिए AUDIT; डिमेंशिया, मिर्गी और आत्महत्या जोखिम के लिए अन्य मानक टूल।"}],"E-026.1":[{"q":"Does asking a person directly about thoughts of suicide increase their risk?","qh":"क्या किसी व्यक्ति से आत्महत्या के विचारों के बारे में सीधे पूछने से उसका जोखिम बढ़ता है?","o":["Yes, it should never be asked","No — asking calmly and directly helps identify risk and get support","Only if asked by a doctor","Only in adolescents"],"oh":["हाँ, कभी नहीं पूछना चाहिए","नहीं — शांति से सीधे पूछने से जोखिम पहचानने और मदद दिलाने में सहायता मिलती है","केवल डॉक्टर पूछें तो","केवल किशोरों में"],"a":1,"x":"Asking about suicide does not plant the idea; it opens the conversation. Anyone at high risk is not left alone and is referred urgently.","xh":"आत्महत्या के बारे में पूछने से यह विचार नहीं आता; बात शुरू होती है। उच्च जोखिम वाले व्यक्ति को अकेला न छोड़ें और तुरंत रेफर करें।"}],"E-027.1":[{"q":"A person has a seizure lasting more than 5 minutes. What is the emergency management at the facility?","qh":"किसी व्यक्ति का दौरा 5 मिनट से अधिक चल रहा है। केंद्र पर आपातकालीन प्रबंधन क्या है?","o":["Put a spoon in the mouth and hold the limbs down","Place on the side, protect from injury, give midazolam (intranasal/IM) as per protocol, and refer","Pour water on the face","Give food to bring the person round"],"oh":["मुँह में चम्मच डालें और हाथ-पैर पकड़ें","करवट पर लिटाएँ, चोट से बचाएँ, प्रोटोकॉल अनुसार मिडाज़ोलम (नाक से/IM) दें, और रेफर करें","चेहरे पर पानी डालें","होश में लाने के लिए खाना खिलाएँ"],"a":1,"x":"Recovery position, nothing in the mouth, protect from injury, midazolam intranasal or IM for prolonged seizures, then refer.","xh":"करवट वाली स्थिति, मुँह में कुछ न डालें, चोट से बचाएँ, लंबे दौरे में नाक से या IM मिडाज़ोलम, फिर रेफर करें।"}],"E-002.1":[{"q":"In adult basic life support (CPR), what is the correct rate of chest compressions?","qh":"वयस्क बेसिक लाइफ़ सपोर्ट (CPR) में छाती दबाने की सही गति क्या है?","o":["40–60 per minute","60–80 per minute","100–120 per minute","150–180 per minute"],"oh":["40–60 प्रति मिनट","60–80 प्रति मिनट","100–120 प्रति मिनट","150–180 प्रति मिनट"],"a":2,"x":"Push hard and fast in the centre of the chest: 100–120 per minute, 5–6 cm deep, 30 compressions to 2 breaths, and call for help/ambulance first.","xh":"छाती के बीच में ज़ोर से और तेज़ दबाएँ: 100–120 प्रति मिनट, 5–6 cm गहरा, 30 दबाव पर 2 साँस, और पहले मदद/एम्बुलेंस बुलाएँ।"}],"E-002.2":[{"q":"Which signs suggest a stroke?","qh":"कौन-से संकेत स्ट्रोक (लकवे का दौरा) दर्शाते हैं?","o":["Sudden face drooping, arm weakness on one side, or slurred speech","Fever with cough","Pain in both knees","Itching all over the body"],"oh":["अचानक चेहरा टेढ़ा होना, एक तरफ़ हाथ में कमज़ोरी, या बोलने में लड़खड़ाहट","खाँसी के साथ बुखार","दोनों घुटनों में दर्द","पूरे शरीर में खुजली"],"a":0,"x":"FAST: Face drooping, Arm weakness, Speech difficulty — Time to call the ambulance; treatment works best within the first hours.","xh":"FAST: चेहरा टेढ़ा (Face), हाथ में कमज़ोरी (Arm), बोलने में कठिनाई (Speech) — एम्बुलेंस बुलाने का समय (Time); इलाज पहले कुछ घंटों में सबसे असरदार होता है।"}],"E-005.1":[{"q":"In triage during a mass casualty, what does a RED tag mean?","qh":"बड़ी दुर्घटना में ट्राइएज के दौरान लाल टैग का क्या अर्थ है?","o":["Dead","Minor injury, can walk","Life-threatening — needs immediate care and transfer first","Can wait for a few hours"],"oh":["मृत","मामूली चोट, चल सकता है","जान का खतरा — तुरंत देखभाल और पहले भेजना","कुछ घंटे इंतज़ार कर सकता है"],"a":2,"x":"Red = immediate; yellow = urgent but can wait a little; green = minor (\"walking wounded\"); black = dead or not expected to survive.","xh":"लाल = तुरंत; पीला = ज़रूरी पर थोड़ा इंतज़ार कर सकता है; हरा = मामूली (चल सकने वाले); काला = मृत या बचने की उम्मीद नहीं।"}],"A-042.1":[{"q":"What is the correct first aid for a snake bite?","qh":"साँप काटने पर सही प्राथमिक उपचार क्या है?","o":["Tie a tight tourniquet and cut the bite to suck out the venom","Reassure, keep the bitten limb still like a fracture, remove rings or tight items, and take the person quickly to a facility with anti-snake venom","Apply ice and wait to see if symptoms come","Give alcohol for the pain"],"oh":["कसकर पट्टी बाँधें और काटी जगह चीरकर ज़हर चूसें","आश्वस्त करें, काटे अंग को टूटी हड्डी की तरह स्थिर रखें, अंगूठी या कसी चीज़ें उतारें, और जल्दी से एंटी-स्नेक वेनम वाले केंद्र पहुँचाएँ","बर्फ़ लगाकर लक्षणों का इंतज़ार करें","दर्द के लिए शराब दें"],"a":1,"x":"Do it R.I.G.H.T.: Reassure, Immobilise, Go to hospital, Tell the doctor of symptoms. No tourniquet, cutting, sucking or ice.","xh":"R.I.G.H.T. करें: आश्वस्त करें, स्थिर रखें, अस्पताल जाएँ, डॉक्टर को लक्षण बताएँ। न कसी पट्टी, न चीरा, न चूसना, न बर्फ़।"}],"E-185.1":[{"q":"Which of these is one of the \"rights\" of safe medication?","qh":"इनमें से कौन-सा सुरक्षित दवा देने के \"सही\" में से एक है?","o":["Right patient","Right price","Right brand","Right colour"],"oh":["सही रोगी","सही कीमत","सही ब्रांड","सही रंग"],"a":0,"x":"The rights: right patient, right drug, right dose, right route, right time and right documentation.","xh":"सही: सही रोगी, सही दवा, सही खुराक, सही तरीका, सही समय और सही दस्तावेज़।"}],"E-181.2":[{"q":"A prescription from the PHC is unclear (handwriting or an abbreviation). What should the CHO do?","qh":"PHC का पर्चा स्पष्ट नहीं है (लिखावट या संक्षिप्त शब्द)। CHO को क्या करना चाहिए?","o":["Guess the most likely drug","Confirm with the prescriber before giving the drug","Ask the patient what they think it says","Skip the drug"],"oh":["सबसे संभावित दवा का अनुमान लगाएँ","दवा देने से पहले लिखने वाले डॉक्टर से पुष्टि करें","रोगी से पूछें कि उसे क्या लगता है","वह दवा छोड़ दें"],"a":1,"x":"Never guess. Confirm unclear orders with the prescriber (phone/teleconsultation) and record the confirmation.","xh":"कभी अनुमान न लगाएँ। अस्पष्ट आदेश की लिखने वाले से (फ़ोन/टेली-परामर्श) पुष्टि करें और उसे दर्ज करें।"}],"E-182.1":[{"q":"Can a single-dose vial or ampoule be used for two patients if some medicine is left?","qh":"अगर कुछ दवा बची हो तो क्या एक-खुराक वायल या एम्प्यूल दो रोगियों के लिए इस्तेमाल हो सकता है?","o":["Yes, if used the same day","No — a single-dose vial is used once and the rest is discarded","Yes, if kept in the fridge","Yes, with a new needle"],"oh":["हाँ, अगर उसी दिन इस्तेमाल हो","नहीं — एक-खुराक वायल एक बार इस्तेमाल होता है और बाकी फेंक दिया जाता है","हाँ, अगर फ्रिज में रखा हो","हाँ, नई सुई से"],"a":1,"x":"Single-dose vials and ampoules are used for one dose only; use a new sterile needle and syringe every time.","xh":"एक-खुराक वायल और एम्प्यूल केवल एक खुराक के लिए हैं; हर बार नई जीवाणुरहित सुई और सिरिंज का उपयोग करें।"}],"F-006.1":[{"q":"Which of these is one of the five moments of hand hygiene?","qh":"इनमें से कौन-सा हाथ की सफ़ाई के पाँच क्षणों में से एक है?","o":["Before touching a patient","Before opening the register","After switching on the fan","Before answering the phone"],"oh":["रोगी को छूने से पहले","रजिस्टर खोलने से पहले","पंखा चालू करने के बाद","फ़ोन उठाने से पहले"],"a":0,"x":"Five moments: before touching a patient, before a clean/aseptic procedure, after body fluid exposure risk, after touching a patient, and after touching patient surroundings.","xh":"पाँच क्षण: रोगी को छूने से पहले, साफ़/एसेप्टिक प्रक्रिया से पहले, शरीर के तरल के संपर्क के जोखिम के बाद, रोगी को छूने के बाद, और रोगी के आसपास की चीज़ें छूने के बाद।"}],"F-008.1":[{"q":"When taking off (doffing) PPE, what is usually removed first?","qh":"PPE उतारते (डॉफ़िंग) समय आमतौर पर सबसे पहले क्या उतारा जाता है?","o":["The mask","The gloves (most contaminated)","The cap","The shoe covers last, then the gloves"],"oh":["मास्क","दस्ताने (सबसे दूषित)","टोपी","पहले जूते के कवर, फिर दस्ताने"],"a":1,"x":"Doffing starts with the most contaminated items (gloves, then gown), with hand hygiene between steps; the mask is removed last, from behind, without touching the front.","xh":"उतारना सबसे दूषित चीज़ों (दस्ताने, फिर गाउन) से शुरू होता है, हर कदम के बीच हाथ साफ़ करें; मास्क सबसे अंत में, पीछे से, आगे का हिस्सा छुए बिना उतारें।"}],"F-010.3":[{"q":"How is 0.5% chlorine solution made from bleaching powder (30% available chlorine)?","qh":"ब्लीचिंग पाउडर (30% उपलब्ध क्लोरीन) से 0.5% क्लोरीन घोल कैसे बनाया जाता है?","o":["About 17 g in 1 litre of water","1 g in 10 litres of water","100 g in 1 litre of water","Any amount until it smells strong"],"oh":["लगभग 17 g 1 लीटर पानी में","1 g 10 लीटर पानी में","100 g 1 लीटर पानी में","तेज़ गंध आने तक कितना भी"],"a":0,"x":"Grams per litre = (0.5 ÷ 30) × 1000 ≈ 17 g of bleaching powder (30%) per litre for 0.5% chlorine; make it fresh daily and keep it covered.","xh":"ग्राम प्रति लीटर = (0.5 ÷ 30) × 1000 ≈ 17 g ब्लीचिंग पाउडर (30%) प्रति लीटर से 0.5% क्लोरीन बनता है; रोज़ ताज़ा बनाएँ और ढककर रखें।"}],"F-012.1":[{"q":"How long must instruments be boiled for high-level disinfection (HLD)?","qh":"उच्च-स्तरीय कीटाणुशोधन (HLD) के लिए उपकरणों को कितनी देर उबालना चाहिए?","o":["5 minutes","20 minutes after the water starts boiling","2 hours","Until the water turns cloudy"],"oh":["5 मिनट","पानी उबलना शुरू होने के बाद 20 मिनट","2 घंटे","पानी धुंधला होने तक"],"a":1,"x":"Boil for 20 minutes counted from when the water starts boiling, with instruments fully covered; nothing is added once timing starts. Sterilisation (autoclave) is a higher level.","xh":"पानी उबलना शुरू होने से 20 मिनट गिनें, उपकरण पूरी तरह डूबे हों; समय शुरू होने के बाद कुछ न डालें। स्टरलाइज़ेशन (ऑटोक्लेव) इससे ऊँचा स्तर है।"}],"F-015.1":[{"q":"In which container do used needles go?","qh":"इस्तेमाल हुई सुइयाँ किस पात्र में जाती हैं?","o":["Yellow bag","Red bag","White (translucent) puncture-proof container","Black bag with general waste"],"oh":["पीला थैला","लाल थैला","सफ़ेद (पारदर्शी) पंक्चर-प्रूफ़ पात्र","सामान्य कचरे के साथ काला थैला"],"a":2,"x":"Sharps (needles, blades) go in the white translucent puncture-proof container; glass in blue; contaminated plastics (tubing, catheters, gloves) in red; soiled dressings and anatomical waste in yellow.","xh":"नुकीली चीज़ें (सुई, ब्लेड) सफ़ेद पारदर्शी पंक्चर-प्रूफ़ पात्र में; काँच नीले में; दूषित प्लास्टिक (ट्यूब, कैथेटर, दस्ताने) लाल में; गंदी पट्टियाँ और शारीरिक अंग पीले में।"}],"F-017.1":[{"q":"For how long at most may biomedical waste be stored at the facility before it is collected?","qh":"बायोमेडिकल कचरा केंद्र पर उठाए जाने से पहले अधिकतम कितने समय तक रखा जा सकता है?","o":["12 hours","48 hours","7 days","Until the bins are full"],"oh":["12 घंटे","48 घंटे","7 दिन","डिब्बे भरने तक"],"a":1,"x":"Untreated biomedical waste must not be stored beyond 48 hours.","xh":"बिना उपचारित बायोमेडिकल कचरा 48 घंटे से अधिक नहीं रखा जाना चाहिए।"}],"F-020.1":[{"q":"A staff member gets a needle-stick injury. What is the correct first step?","qh":"किसी कर्मचारी को सुई चुभ गई है। पहला सही कदम क्या है?","o":["Squeeze the wound hard and put bleach on it","Wash with soap and running water, do not squeeze or scrub, report at once, and get assessed for PEP (ideally within 2 hours, up to 72 hours)","Ignore it if there is no bleeding","Wait for the patient's HIV report before telling anyone"],"oh":["घाव को ज़ोर से दबाएँ और ब्लीच लगाएँ","साबुन और बहते पानी से धोएँ, न दबाएँ न रगड़ें, तुरंत रिपोर्ट करें, और PEP के लिए जाँच कराएँ (हो सके तो 2 घंटे में, 72 घंटे तक)","खून न निकले तो अनदेखा करें","किसी को बताने से पहले रोगी की HIV रिपोर्ट का इंतज़ार करें"],"a":1,"x":"Wash with soap and water; do not squeeze, scrub or use bleach. Report immediately and get PEP assessment — start as early as possible, within 72 hours.","xh":"साबुन-पानी से धोएँ; न दबाएँ, न रगड़ें, न ब्लीच लगाएँ। तुरंत रिपोर्ट करें और PEP जाँच कराएँ — जितनी जल्दी हो सके, 72 घंटे के अंदर शुरू करें।"}],"F-022.2":[{"q":"A mercury thermometer breaks and mercury spills on the floor. What is correct?","qh":"पारे वाला थर्मामीटर टूटकर पारा फ़र्श पर गिर गया। सही क्या है?","o":["Sweep it with a broom","Wear gloves, collect the beads with a card or syringe into a closed container with water, and use the spill kit","Wash it into the drain","Pick it up with bare hands"],"oh":["झाड़ू से साफ़ करें","दस्ताने पहनें, कार्ड या सिरिंज से बूँदें इकट्ठा कर पानी वाले बंद पात्र में रखें, और स्पिल किट का उपयोग करें","नाली में बहा दें","नंगे हाथों से उठाएँ"],"a":1,"x":"Never sweep, vacuum or wash mercury down the drain. Ventilate the room, wear gloves and mask, collect with card/syringe into a sealed container with water, and hand over as hazardous waste.","xh":"पारे को कभी झाड़ू, वैक्यूम या नाली से साफ़ न करें। कमरा हवादार करें, दस्ताने-मास्क पहनें, कार्ड/सिरिंज से पानी वाले बंद पात्र में इकट्ठा करें, और खतरनाक कचरे के रूप में सौंपें।"}],"D-008.1":[{"q":"Why are two buckets used when mopping the floor?","qh":"फ़र्श पोंछते समय दो बाल्टियाँ क्यों इस्तेमाल की जाती हैं?","o":["One for the floor of each room","One holds the cleaning solution, the other is for rinsing/wringing the dirty mop, so the solution stays clean","To carry more water","One for the morning and one for the evening"],"oh":["हर कमरे के फ़र्श के लिए एक","एक में सफ़ाई का घोल, दूसरी में गंदा पोंछा धोने/निचोड़ने के लिए, ताकि घोल साफ़ रहे","ज़्यादा पानी ले जाने के लिए","एक सुबह के लिए, एक शाम के लिए"],"a":1,"x":"The two-bucket method keeps dirty water out of the cleaning solution, so dirt and germs are not spread back onto the floor.","xh":"दो-बाल्टी तरीके से गंदा पानी सफ़ाई के घोल में नहीं मिलता, इसलिए गंदगी और कीटाणु वापस फ़र्श पर नहीं फैलते।"}],"C-008.3":[{"q":"In using a fire extinguisher, what does PASS stand for?","qh":"अग्निशामक के उपयोग में PASS का अर्थ क्या है?","o":["Push, Alarm, Spray, Stop","Pull the pin, Aim at the base of the fire, Squeeze the lever, Sweep side to side","Point, Aim, Shoot, Save","Pull, Alert, Spray, Shout"],"oh":["Push, Alarm, Spray, Stop","पिन खींचें (Pull), आग के आधार पर निशाना (Aim), लीवर दबाएँ (Squeeze), दाएँ-बाएँ घुमाएँ (Sweep)","Point, Aim, Shoot, Save","Pull, Alert, Spray, Shout"],"a":1,"x":"PASS: Pull the pin, Aim at the base of the fire, Squeeze the lever, Sweep from side to side.","xh":"PASS: पिन खींचें, आग के आधार पर निशाना लगाएँ, लीवर दबाएँ, दाएँ-बाएँ घुमाएँ।"}],"D-016.3":[{"q":"What is the \"holdover time\" of a vaccine refrigerator or ice-lined refrigerator?","qh":"वैक्सीन रेफ्रिजरेटर या ILR का \"होल्डओवर टाइम\" क्या है?","o":["The time it takes to cool down after switching on","How long it keeps vaccines in the safe range (+2 to +8 °C) during a power cut","The time between two defrostings","The shelf life of the vaccines inside"],"oh":["चालू करने के बाद ठंडा होने में लगने वाला समय","बिजली जाने पर वह कितनी देर टीकों को सुरक्षित तापमान (+2 से +8 °C) में रखता है","दो डीफ़्रॉस्ट के बीच का समय","अंदर रखे टीकों की शेल्फ़ लाइफ़"],"a":1,"x":"Holdover time is how long the equipment keeps vaccines at +2 to +8 °C without power; staff use it to plan what to do in an outage.","xh":"होल्डओवर टाइम वह समय है जब तक उपकरण बिना बिजली टीकों को +2 से +8 °C पर रखता है; बिजली जाने पर क्या करना है, यह इसी से तय होता है।"}],"E-074.2":[{"q":"At what age should complementary food be started, with continued breastfeeding?","qh":"स्तनपान जारी रखते हुए ऊपरी आहार (पूरक आहार) किस उम्र में शुरू करना चाहिए?","o":["At 3 months","At 6 months (completed 180 days)","At 1 year","When the first tooth comes"],"oh":["3 महीने पर","6 महीने पर (180 दिन पूरे होने पर)","1 वर्ष पर","पहला दाँत आने पर"],"a":1,"x":"Exclusive breastfeeding for 6 months; complementary food from 6 months, with breastfeeding continued up to 2 years or beyond.","xh":"6 महीने तक केवल स्तनपान; 6 महीने से ऊपरी आहार, और स्तनपान 2 वर्ष या उससे आगे तक जारी।"}],"E-077.2":[{"q":"How can people recognise fortified food (e.g. salt, oil, rice) in the market?","qh":"लोग बाज़ार में फ़ोर्टिफ़ाइड भोजन (जैसे नमक, तेल, चावल) कैसे पहचान सकते हैं?","o":["By a green dot","By the \"+F\" logo on the pack","By the ISI mark only","By a higher price"],"oh":["हरे बिंदु से","पैकेट पर \"+F\" लोगो से","केवल ISI चिह्न से","ज़्यादा कीमत से"],"a":1,"x":"The FSSAI \"+F\" logo marks fortified food. (The green dot means vegetarian; ISI is a product-quality mark.)","xh":"FSSAI का \"+F\" लोगो फ़ोर्टिफ़ाइड भोजन दर्शाता है। (हरा बिंदु शाकाहारी है; ISI उत्पाद-गुणवत्ता चिह्न है।)"}]};
var SC_BLS={"A-002.1":{"b":{"t":"The referral register shows high-risk pregnancies referred, with the first aid given noted.","h":"रेफ़रल रजिस्टर में उच्च-जोखिम गर्भवती महिलाओं का रेफ़रल और दी गई प्राथमिक चिकित्सा दर्ज हो।","m":"RR"}},"A-004.1":{"b":{"t":"PPH, eclampsia and sepsis referrals are recorded in the referral register.","h":"PPH, एक्लेम्पसिया और सेप्सिस के रेफ़रल रेफ़रल रजिस्टर में दर्ज हों।","m":"RR"}},"A-005.1":{"b":{"t":"Referral entries exist for low-birth-weight, preterm and sick newborns.","h":"कम वज़न, समय से पहले जन्मे और बीमार नवजातों के रेफ़रल दर्ज हों।","m":"RR"}},"A-014.1":{"b":{"t":"Presumptive TB cases are recorded (register / Ni-kshay).","h":"संभावित TB मामले दर्ज हों (रजिस्टर / नि-क्षय)।","m":"RR"}},"A-042.1":{"b":{"t":"Emergency cases stabilised and referred are recorded in the referral register.","h":"स्थिर करके रेफ़र किए गए आपात मामले रेफ़रल रजिस्टर में दर्ज हों।","m":"RR"}},"E-006.1":{"b":{"t":"OPD or referral entries show eye conditions identified and referred.","h":"OPD या रेफ़रल प्रविष्टियों में आँख की बीमारियों की पहचान और रेफ़रल दर्ज हो।","m":"RR"}},"E-007.2":{"b":{"t":"OPD or referral entries show eye conditions treated and referred when needed.","h":"OPD या रेफ़रल प्रविष्टियों में आँख की बीमारियों का उपचार और ज़रूरत पर रेफ़रल दर्ज हो।","m":"RR"}},"E-039.1":{"b":{"t":"Records show follow-up at 6, 12, 18 and 24 months after TB treatment.","h":"रिकॉर्ड में TB इलाज के बाद 6, 12, 18 और 24 महीने पर फ़ॉलो-अप दर्ज हो।","m":"RR"}},"E-052.1":{"b":{"t":"CBAC forms and the NCD portal show hypertension screening, referral and follow-up.","h":"CBAC फ़ॉर्म और NCD पोर्टल में उच्च रक्तचाप की जाँच, रेफ़रल और फ़ॉलो-अप दर्ज हो।","m":"RR"}},"E-105.1":{"b":{"t":"Any AEFI case is recorded and reported in the AEFI format.","h":"हर AEFI मामला AEFI फ़ॉर्मेट में दर्ज और रिपोर्ट हो।","m":"RR"}},"E-106.1":{"b":{"t":"AEFI reports (if any) show they reached the PHC MO / District Immunization Officer.","h":"AEFI रिपोर्ट (यदि कोई हो) PHC चिकित्सा अधिकारी / ज़िला प्रतिरक्षण अधिकारी तक पहुँचना दर्शाएँ।","m":"RR"}},"E-109.1":{"b":{"t":"Child OPD records show breathing rate and chest in-drawing checked for cough cases.","h":"बच्चों के OPD रिकॉर्ड में खाँसी के मामलों में साँस दर और छाती धँसने की जाँच दर्ज हो।","m":"RR"}},"E-109.2":{"b":{"t":"Child records show weight-for-age / MUAC checked.","h":"बच्चों के रिकॉर्ड में उम्र के अनुसार वज़न / MUAC की जाँच दर्ज हो।","m":"RR"}},"E-109.3":{"b":{"t":"Child OPD records show dehydration assessed for diarrhoea cases.","h":"बच्चों के OPD रिकॉर्ड में दस्त के मामलों में पानी की कमी का आकलन दर्ज हो।","m":"RR"}},"E-127.1":{"b":{"t":"The ANC register shows most registrations within 12 weeks and a line list of high-risk cases.","h":"ANC रजिस्टर में अधिकतर पंजीकरण 12 सप्ताह के अंदर और उच्च-जोखिम मामलों की सूची हो।","m":"RR"}},"E-133.1":{"b":{"t":"EDD is written in the ANC record / MCP card.","h":"ANC रिकॉर्ड / MCP कार्ड में EDD लिखी हो।","m":"RR"}},"E-136.2":{"b":{"t":"Foetal heart sound is recorded in ANC records.","h":"ANC रिकॉर्ड में भ्रूण की धड़कन दर्ज हो।","m":"RR"}},"E-139.1":{"b":{"t":"Referral entries exist for high-risk pregnancies.","h":"उच्च-जोखिम गर्भावस्थाओं के रेफ़रल दर्ज हों।","m":"RR"}},"E-150.1":{"b":{"t":"Delivery records show episiotomy only with a recorded reason.","h":"प्रसव रिकॉर्ड में एपिसियोटॉमी केवल दर्ज कारण के साथ हो।","m":"RR"}},"E-151.1":{"b":{"t":"Delivery records show AMTSL done for every delivery.","h":"प्रसव रिकॉर्ड में हर प्रसव में AMTSL दर्ज हो।","m":"RR"}},"E-155.2":{"b":{"t":"Vitamin K given at birth is recorded.","h":"जन्म पर दिया गया विटामिन K दर्ज हो।","m":"RR"}},"F-020.1":{"b":{"t":"Any reported exposure has a record of reporting and PEP / treatment.","h":"हर रिपोर्ट किए गए संपर्क (सुई चुभना आदि) की रिपोर्ट और PEP / उपचार दर्ज हो।","m":"RR"}},"E-014.2":{"b":{"t":"OPD or referral entries show nose problems treated and referred when needed.","h":"OPD या रेफ़रल प्रविष्टियों में नाक की समस्याओं का उपचार और ज़रूरत पर रेफ़रल दर्ज हो।","m":"RR"}},"E-021.1":{"b":{"t":"OPD or referral entries show dental problems given relief and referred.","h":"OPD या रेफ़रल प्रविष्टियों में दाँत की समस्याओं में राहत और रेफ़रल दर्ज हो।","m":"RR"}},"E-025.2":{"b":{"t":"Filled screening tools (e.g. PHQ-9, AUDIT) are on record.","h":"भरे हुए जाँच टूल (जैसे PHQ-9, AUDIT) रिकॉर्ड में हों।","m":"RR"}},"E-027.1":{"b":{"t":"Seizure cases managed and referred are recorded.","h":"संभाले और रेफ़र किए गए दौरे के मामले दर्ज हों।","m":"RR"}},"E-032.1":{"b":{"t":"Referral entries exist for malaria cases with danger signs.","h":"खतरे के संकेत वाले मलेरिया मामलों के रेफ़रल दर्ज हों।","m":"RR"}},"E-060.2":{"b":{"t":"Screening records show waist size and BMI for people at risk.","h":"जाँच रिकॉर्ड में जोखिम वाले लोगों की कमर का नाप और BMI दर्ज हो।","m":"RR"}},"E-066.1":{"b":{"t":"VIA screening is recorded.","h":"VIA जाँच दर्ज हो।","m":"RR"}},"E-089.1":{"b":{"t":"HBNC or referral records show sick newborns identified and referred.","h":"HBNC या रेफ़रल रिकॉर्ड में बीमार नवजातों की पहचान और रेफ़रल दर्ज हो।","m":"RR"}},"E-110.1":{"b":{"t":"Records show sick young infants assessed and referred.","h":"रिकॉर्ड में बीमार छोटे शिशुओं का आकलन और रेफ़रल दर्ज हो।","m":"RR"}},"E-110.2":{"b":{"t":"Records show children with cough classified (pneumonia / no pneumonia).","h":"रिकॉर्ड में खाँसी वाले बच्चों का वर्गीकरण (निमोनिया / निमोनिया नहीं) दर्ज हो।","m":"RR"}},"E-111.1":{"b":{"t":"OPD records show ORS and zinc given for diarrhoea.","h":"OPD रिकॉर्ड में दस्त के लिए ORS और ज़िंक दिया जाना दर्ज हो।","m":"RR"}},"E-112.1":{"b":{"t":"OPD records show ARI cases managed and advised.","h":"OPD रिकॉर्ड में ARI मामलों का प्रबंधन और सलाह दर्ज हो।","m":"RR"}},"E-113.1":{"b":{"t":"Referral records show the pre-referral dose was given.","h":"रेफ़रल रिकॉर्ड में रेफ़रल से पहले दी गई खुराक दर्ज हो।","m":"RR"}},"E-116.1":{"b":{"t":"The FP register shows clients counselled on methods.","h":"FP रजिस्टर में तरीकों पर परामर्श पाए लोगों का रिकॉर्ड हो।","m":"RR"}},"E-118.1":{"b":{"t":"The eligible couple register is up to date.","h":"योग्य दंपत्ति रजिस्टर अद्यतन हो।","m":"RR"}},"E-122.1":{"b":{"t":"Records show sterilisation clients counselled and referred.","h":"रिकॉर्ड में नसबंदी के इच्छुक लोगों का परामर्श और रेफ़रल दर्ज हो।","m":"RR"}},"E-123.1":{"b":{"t":"Follow-up of women after sterilisation is recorded.","h":"नसबंदी के बाद महिलाओं का फ़ॉलो-अप दर्ज हो।","m":"RR"}},"E-123.2":{"b":{"t":"Follow-up of men after vasectomy (semen test at 3 months) is recorded.","h":"पुरुष नसबंदी के बाद फ़ॉलो-अप (3 महीने पर वीर्य जाँच) दर्ज हो।","m":"RR"}},"E-140.1":{"b":{"t":"ANC records show BP measured at every visit.","h":"ANC रिकॉर्ड में हर जाँच पर BP दर्ज हो।","m":"RR"}},"E-149.1":{"b":{"t":"Delivery records / the delivery kit show the six cleans are followed.","h":"प्रसव रिकॉर्ड / प्रसव किट से छह साफ़ का पालन दिखे।","m":"RR"}},"E-150.2":{"b":{"t":"Delivery records show no oxytocin or misoprostol before birth without a clear reason.","h":"प्रसव रिकॉर्ड में बिना स्पष्ट कारण जन्म से पहले ऑक्सीटोसिन या मिसोप्रोस्टोल न दिखे।","m":"RR"}},"E-152.1":{"b":{"t":"Delivery records show oxytocin 10 IU IM given within 1 minute of birth.","h":"प्रसव रिकॉर्ड में जन्म के 1 मिनट के अंदर ऑक्सीटोसिन 10 IU IM दर्ज हो।","m":"RR"}},"E-157.2":{"b":{"t":"A partograph is filled for every delivery.","h":"हर प्रसव के लिए पार्टोग्राफ़ भरा हो।","m":"RR"}},"E-158.2":{"b":{"t":"Records of eclampsia cases show the magnesium sulphate dose and referral.","h":"एक्लेम्पसिया मामलों के रिकॉर्ड में मैग्नीशियम सल्फेट की खुराक और रेफ़रल दर्ज हो।","m":"RR"}},"E-159.2":{"b":{"t":"Records of PPH cases show management and referral.","h":"PPH मामलों के रिकॉर्ड में प्रबंधन और रेफ़रल दर्ज हो।","m":"RR"}},"E-051.1":{"b":{"t":"Hepatitis B birth doses given are recorded.","h":"दी गई हेपेटाइटिस B जन्म-खुराक दर्ज हो।","m":"RR"}},"D-008.1":{"b":{"t":"Two buckets are seen in use for mopping.","h":"पोंछे के लिए दो बाल्टियों का उपयोग होता दिखे।","m":"OB"}},"E-182.1":{"b":{"t":"Observe: expiry checked, single-dose vials used once, a new sterile needle each time.","h":"देखें: समाप्ति तारीख जाँची जाए, एक-खुराक वायल एक बार ही, हर बार नई जीवाणुरहित सुई।","m":"OB"}},"E-100.1":{"b":{"t":"Observe at the end of a session: vials in a zip bag in the carrier, returned through AVD.","h":"सत्र के अंत में देखें: वायल ज़िप बैग में कैरियर में, AVD से वापसी।","m":"OB"}},"E-154.1":{"b":{"t":"Demonstration or observed case: cord clamped and cut at 1–3 minutes.","h":"प्रदर्शन या देखा गया मामला: नाल 1–3 मिनट पर बाँधी और काटी गई।","m":"OB"}},"E-156.1":{"b":{"t":"Demonstration: newborn resuscitation done correctly on a mannequin.","h":"प्रदर्शन: मैनिकिन पर नवजात पुनर्जीवन सही ढंग से किया जाए।","m":"OB"}},"F-006.1":{"b":{"t":"Demonstration and random observation: six steps of hand washing at the five moments.","h":"प्रदर्शन और अचानक अवलोकन: पाँच क्षणों पर हाथ धोने के छह चरण।","m":"OB"}},"F-008.1":{"b":{"t":"Demonstration: donning and doffing PPE in the correct order.","h":"प्रदर्शन: सही क्रम में PPE पहनना और उतारना।","m":"OB"}},"F-015.1":{"b":{"t":"Observe: waste is in the correct colour-coded bins.","h":"देखें: कचरा सही रंग के डिब्बों में हो।","m":"OB"}},"F-017.1":{"b":{"t":"Observe: no biomedical waste older than 48 hours; collection is recorded.","h":"देखें: 48 घंटे से पुराना बायोमेडिकल कचरा न हो; उठाव दर्ज हो।","m":"OB"}},"F-022.2":{"b":{"t":"A mercury spill kit is available.","h":"पारा स्पिल किट उपलब्ध हो।","m":"OB"}},"E-147.2":{"b":{"t":"Ask 2–3 recently delivered mothers: they were told to start breastfeeding within an hour and to give only breast milk for six months.","h":"हाल में प्रसव हुई 2–3 माताओं से पूछें: उन्हें एक घंटे के अंदर स्तनपान शुरू करने और छह महीने केवल माँ का दूध देने को बताया गया।","m":"CI"}},"E-147.3":{"b":{"t":"Ask 2–3 recently delivered mothers: they were told about family planning options after delivery.","h":"हाल में प्रसव हुई 2–3 माताओं से पूछें: उन्हें प्रसव के बाद परिवार नियोजन के विकल्प बताए गए।","m":"CI"}},"E-074.2":{"b":{"t":"Ask 2–3 mothers of infants: they know about exclusive breastfeeding for 6 months and starting complementary food at 6 months.","h":"शिशुओं की 2–3 माताओं से पूछें: उन्हें 6 महीने केवल स्तनपान और 6 महीने पर ऊपरी आहार शुरू करने की जानकारी हो।","m":"CI"}},"E-077.2":{"b":{"t":"Ask 2–3 people: they can recognise fortified food by the +F logo.","h":"2–3 लोगों से पूछें: वे +F लोगो से फ़ोर्टिफ़ाइड भोजन पहचान सकें।","m":"CI"}},"A-005.2":{"b":{"t":"OPD and referral entries exist for sick infants (ARI, diarrhoea, jaundice, anaemia, malnutrition, developmental delay).","h":"बीमार शिशुओं (ARI, दस्त, पीलिया, एनीमिया, कुपोषण, विकास में देरी) की OPD और रेफ़रल प्रविष्टियाँ हों।","m":"RR"},"a":{"t":"Infants: staff identify, manage and refer ARI, diarrhoea, jaundice, anaemia, malnutrition and developmental delay.","h":"शिशु: स्टाफ़ ARI, दस्त, पीलिया, एनीमिया, कुपोषण और विकास में देरी की पहचान, प्रबंधन और रेफ़रल करे।"}},"A-053.1":{"b":{"t":"Essential newborn care is recorded for each delivery.","h":"हर प्रसव में आवश्यक नवजात देखभाल दर्ज हो।","m":"RR"},"a":{"t":"Ask the staff to describe essential newborn care, including newborn resuscitation.","h":"स्टाफ़ से आवश्यक नवजात देखभाल, जिसमें नवजात पुनर्जीवन शामिल है, बताने को कहें और देखें कि यह हर प्रसव के लिए दर्ज हो।"}},"A-007.1":{"b":{"t":"OPD and referral entries show common childhood illnesses treated, referred and followed up.","h":"OPD और रेफ़रल प्रविष्टियों में बच्चों की सामान्य बीमारियों का उपचार, रेफ़रल और फ़ॉलो-अप दर्ज हो।","m":"RR"},"a":{"t":"Ask the CHO how she identifies, treats, refers and follows up anaemia, malnutrition, vaccine-preventable diseases, ARI, diarrhoea, fever, ENT problems, skin infections, worms, poisoning, injuries, the 4 Ds and sickle cell anaemia.","h":"CHO से पूछें कि वे एनीमिया, कुपोषण, टीके से रोके जा सकने वाले रोग, ARI, दस्त, बुख़ार, ENT समस्याएँ, त्वचा संक्रमण, कृमि, ज़हर, चोट, 4D और सिकल सेल एनीमिया की पहचान, इलाज, रेफ़रल और फ़ॉलो-अप कैसे करती हैं।"}},"A-023.1":{"b":{"t":"OPD entries show common illnesses treated and referred.","h":"OPD प्रविष्टियों में सामान्य बीमारियों का उपचार और रेफ़रल दर्ज हो।","m":"RR"},"a":{"t":"Ask the CHO how she identifies, treats and refers fever, URI/ARI, diarrhoea, scabies, rashes/urticaria, abscess, cholera, dysentery, typhoid, worm infestation, headache and body/joint aches.","h":"CHO से पूछें कि वे बुख़ार, URI/ARI, दस्त, खुजली, चकत्ते/पित्ती, फोड़ा, हैज़ा, पेचिश, टाइफ़ाइड, कृमि, सिरदर्द और शरीर/जोड़ों के दर्द की पहचान, इलाज और रेफ़रल कैसे करती हैं।"}},"A-035.1":{"b":{"t":"OPD entries show ENT conditions managed and referred.","h":"OPD प्रविष्टियों में ENT समस्याओं का प्रबंधन और रेफ़रल दर्ज हो।","m":"RR"},"a":{"t":"Ask the CHO how she identifies, manages and (if needed) refers common cold/URI, tonsillitis, pharyngitis, laryngitis, sinusitis, nose bleed, ear infections (otomycosis, otitis externa, ASOM), foreign bodies/injuries and thyroid swelling.","h":"CHO से पूछें कि वे सर्दी-ज़ुकाम/URI, टॉन्सिल, गले की सूजन, स्वरयंत्र की सूजन, साइनस, नाक से ख़ून, कान के संक्रमण (ओटोमाइकोसिस, ओटाइटिस एक्सटर्ना, ASOM), बाहरी वस्तु/चोट और थायरॉइड की सूजन की पहचान, प्रबंधन और ज़रूरत पड़ने पर रेफ़रल कैसे करती हैं।"}},"A-037.1":{"b":{"t":"Referral entries exist for oral conditions (cleft lip/palate, patches, ulcers, growths).","h":"मुँह की समस्याओं (कटा होंठ/तालू, धब्बे, छाले, गाँठ) के रेफ़रल दर्ज हों।","m":"RR"},"a":{"t":"Ask the CHO how she identifies and refers misaligned teeth/jaws, dental fluorosis, cleft lip and palate, abnormal growths, patches or ulcers and oral cancer.","h":"CHO से पूछें कि वे टेढ़े दाँत/जबड़े, दाँतों का फ़्लोरोसिस, कटे होंठ और तालु, असामान्य उभार, दाग़ या छाले और मुँह के कैंसर की पहचान और रेफ़रल कैसे करती हैं।"}},"A-038.1":{"b":{"t":"OPD entries show dental conditions managed and referred.","h":"OPD प्रविष्टियों में दाँत की समस्याओं का प्रबंधन और रेफ़रल दर्ज हो।","m":"RR"},"a":{"t":"Gum disease (gingivitis, periodontitis), dental caries and dental emergencies (toothache, tooth injury, uncontrolled bleeding, abscess) are managed for symptoms and referred when needed.","h":"मसूड़ों की बीमारी (जिंजिवाइटिस, पेरियोडोंटाइटिस), दाँतों में कीड़ा और दाँतों की आपात स्थितियों (दाँत दर्द, दाँत की चोट, न रुकने वाला ख़ून, फोड़ा) का लक्षण-आधारित प्रबंधन और ज़रूरत पर रेफ़रल हो।"}},"A-043.1":{"b":{"t":"Counselling and referral entries exist for mental health conditions.","h":"मानसिक स्वास्थ्य समस्याओं के परामर्श और रेफ़रल दर्ज हों।","m":"RR"},"a":{"t":"Ask the CHO how she identifies, counsels and refers anxiety, hysteria, depression, neurosis, dementia, intellectual disability and autism.","h":"CHO से पूछें कि वे चिंता, हिस्टीरिया, अवसाद, न्यूरोसिस, डिमेंशिया, बौद्धिक अक्षमता और ऑटिज़्म की पहचान, परामर्श और रेफ़रल कैसे करती हैं।"}},"E-056.1":{"b":{"t":"CBAC forms and the NCD portal show diabetes screening, referral and follow-up.","h":"CBAC फ़ॉर्म और NCD पोर्टल में मधुमेह की जाँच, रेफ़रल और फ़ॉलो-अप दर्ज हो।","m":"RR"},"a":{"t":"Staff can explain the full process for diabetes: CBAC form for everyone above 30, screening on a fixed day, referral of suspected cases for consultation, follow-up of diagnosed patients to keep them on treatment, and referral when warning signs of complications appear.","h":"स्टाफ़ मधुमेह की पूरी प्रक्रिया समझा सके: 30 से ऊपर सभी के लिए CBAC फ़ॉर्म, तय दिन पर स्क्रीनिंग, संदिग्ध मामलों का परामर्श के लिए रेफ़रल, पुष्ट मरीज़ों का फ़ॉलो-अप ताकि इलाज जारी रहे, और जटिलता के चेतावनी लक्षण दिखने पर रेफ़रल।"}},"E-012.2":{"b":{"t":"OPD entries show ear conditions managed (wax, foreign body, symptomatic treatment).","h":"OPD प्रविष्टियों में कान की समस्याओं का प्रबंधन (मैल, बाहरी वस्तु, लक्षण उपचार) दर्ज हो।","m":"RR"},"a":{"t":"Staff can explain first management — ear wax removal (syringing/instruments), foreign body removal, and symptomatic treatment with painkillers, ear drops and warm compresses.","h":"स्टाफ़ प्राथमिक प्रबंधन समझा सके — कान का मैल निकालना (सिरिंजिंग/औज़ार), बाहरी वस्तु निकालना, और दर्द निवारक, कान की बूँदों व गर्म सेंक से लक्षण-आधारित इलाज।"}},"E-024.1":{"b":{"t":"Records show mental disorders identified (screening / OPD).","h":"रिकॉर्ड में मानसिक विकारों की पहचान (जाँच / OPD) दर्ज हो।","m":"RR"},"a":{"t":"Staff can describe common mental disorders (depression, anxiety/panic, psychosomatic), severe mental disorders (schizophrenia, bipolar, severe depression), child and adolescent disorders (conduct disorder, ADHD, oppositional defiant), epilepsy and dementia, and substance use (tobacco, alcohol, drugs).","h":"स्टाफ़ आम मानसिक विकार (अवसाद, चिंता/घबराहट, मनोदैहिक), गंभीर मानसिक विकार (स्किज़ोफ़्रेनिया, बाइपोलर, गंभीर अवसाद), बच्चों और किशोरों के विकार (आचरण विकार, ADHD, विरोधी अवज्ञा), मिर्गी और डिमेंशिया, और नशा (तंबाकू, शराब, ड्रग्स) बता सके।"}},"E-136.1":{"b":{"t":"Fundal height is recorded at each ANC visit.","h":"हर ANC जाँच पर फंडल ऊँचाई दर्ज हो।","m":"RR"},"a":{"t":"Fundal height is measured and staff can relate it to gestational age.","h":"फ़ंडल ऊँचाई नापी जाए और स्टाफ़ उसे गर्भावस्था की अवधि से जोड़ सके।"}},"E-141.1":{"b":{"t":"ANC records show urine albumin tested when BP is high.","h":"ANC रिकॉर्ड में BP अधिक होने पर पेशाब एल्ब्यूमिन जाँच दर्ज हो।","m":"RR"},"a":{"t":"Staff know pre-eclampsia is high BP with urine albumin 2+.","h":"स्टाफ़ को पता हो कि प्री-एक्लेम्पसिया उच्च BP के साथ पेशाब में एल्ब्यूमिन 2+ है।"}},"E-142.1":{"b":{"t":"Referral entries exist for CPD, malpresentation, IUFD and amniotic fluid problems.","h":"CPD, गलत स्थिति, गर्भ में मृत्यु और एमनियोटिक द्रव की समस्याओं के रेफ़रल दर्ज हों।","m":"RR"},"a":{"t":"Staff identify and refer cephalo-pelvic disproportion, malpresentation, medical disorders, intrauterine foetal death and amniotic fluid abnormalities.","h":"स्टाफ़ सिर-श्रोणि असंतुलन, ग़लत स्थिति, चिकित्सा विकार, गर्भ में बच्चे की मृत्यु और एमनियोटिक द्रव की असामान्यताएँ पहचाने और रेफ़र करे।"}}};
